    bool calcQStats(const int whichWorld,
                    const SimTK::Vector& worldBMps,
                    const SimTK::Vector& worldPFrs,
                    const SimTK::Vector& worldQs,
                    int worldNofSamples);
    void printQStats();

    std::vector<SimTK::Real>& getBMps_means(const int whichWorld);
    std::vector<SimTK::Real>& get_dBMps(const int whichWorld);

    std::vector<SimTK::Real>& getPFrs_means(const int whichWorld);
    std::vector<SimTK::Real>& get_dPFrs(const int whichWorld);

    std::vector<SimTK::Real>& getCurrentQs(const int whichWorld);
