    SimTK::Real vdwWellDepthInKJ = SimTK::NaN;
    SimTK::Real sigmaInNm = SimTK::NaN;
    SimTK::Real solventRadiusInNm = SimTK::NaN;
    SimTK::Real screen = SimTK::NaN;

