// Basic functionality for memory management of objects with
// potentially hidden implementations

namespace SimTK {

// The Clonable class is for use on the library side only.  Because it
// has a virtual function table, it is not suitable for crossing
// the library:client API layer.
class Clonable {
public:
    virtual ~Clonable() {};
    virtual Clonable* clone() const = 0;
private:
    // don't permit assignment among all derived classes
    Clonable& operator=(const Clonable &); 
};

}

