    /** Define a custom bond torsion term to be applied to the indicated quadruple
    of atom classes whenever they are found in a 1-2-3-4 bonded sequence. Pass in a
    pointer to a newly-allocated CustomBondTorsion object; the subsystem takes over
    ownership of the object so it should NOT be deleted by the caller.

    @param[in] class1, class2, class3, class4
                                 The atom class quadruple to which this term applies;
                                 1-2-3-4 or 4-3-2-1 order doesn't matter.
    @param[in] bondTorsionTerm   Pointer to a heap-allocated object of a concrete
                                 type derived from DuMM::CustomBondTorsion.
    @see DuMM::CustomBondTorsion
    @see defineBondTorsion() to use the built-in sinusoidal functional form **/
    void defineCustomBondTorsion(DuMM::AtomClassIndex class1,
                                 DuMM::AtomClassIndex class2,
                                 DuMM::AtomClassIndex class3,
                                 DuMM::AtomClassIndex class4,
                                 DuMM::CustomBondTorsion* bondTorsionTerm);

    /** @name               Amber-style improper torsions
    As with normal torsions, (see defineBondTorsion()), only one term may have
    a given periodicity. The amplitudes are in kJ/mol. The third atom is the
    central one to which the other three are bonded; this is not the same in
    reverse order. **/
    /**@{**/

    /** Provide one torsion term in MD units, using kilojoules for amplitude. **/
    void defineAmberImproperTorsion(DuMM::AtomClassIndex class1,
                                    DuMM::AtomClassIndex class2,
                                    DuMM::AtomClassIndex class3,
                                    DuMM::AtomClassIndex class4,
                                    int periodicity,
                                    Real ampInKJ,
                                    Real phaseInDegrees);

    /** Provide two torsion terms in MD units, using kilojoules/mole for
    amplitude. **/
    void defineAmberImproperTorsion(DuMM::AtomClassIndex class1,
                                    DuMM::AtomClassIndex class2,
                                    DuMM::AtomClassIndex class3,
                                    DuMM::AtomClassIndex class4,
                                    int periodicity1,
                                    Real amp1InKJ,
                                    Real phase1InDegrees,
                                    int periodicity2,
                                    Real amp2InKJ,
                                    Real phase2InDegrees);

    /** Provide three torsion terms in MD units, using kilojoules/mole for
    amplitude. **/
    void defineAmberImproperTorsion(DuMM::AtomClassIndex class1,
                                    DuMM::AtomClassIndex class2,
                                    DuMM::AtomClassIndex class3,
                                    DuMM::AtomClassIndex class4,
                                    int periodicity1,
                                    Real amp1InKJ,
                                    Real phase1InDegrees,
                                    int periodicity2,
                                    Real amp2InKJ,
                                    Real phase2InDegrees,
                                    int periodicity3,
                                    Real amp3InKJ,
                                    Real phase3InDegrees);

    /** Provide one torsion term in KA units, using kilocalories/mole for
    amplitude. **/
    void defineAmberImproperTorsion_KA(DuMM::AtomClassIndex class1,
                                       DuMM::AtomClassIndex class2,
                                       DuMM::AtomClassIndex class3,
                                       DuMM::AtomClassIndex class4,
                                       int periodicity1,
                                       Real amp1InKcal,
                                       Real phase1InDegrees) {
        defineAmberImproperTorsion(class1,
                                   class2,
                                   class3,
                                   class4,
                                   periodicity1,
                                   amp1InKcal * DuMM::Kcal2KJ,
                                   phase1InDegrees);
    }

    /** Provide two torsion terms in KA units, using kilocalories/mole for
    amplitude. **/
    void defineAmberImproperTorsion_KA(DuMM::AtomClassIndex class1,
                                       DuMM::AtomClassIndex class2,
                                       DuMM::AtomClassIndex class3,
                                       DuMM::AtomClassIndex class4,
                                       int periodicity1,
                                       Real amp1InKcal,
                                       Real phase1InDegrees,
                                       int periodicity2,
                                       Real amp2InKcal,
                                       Real phase2InDegrees) {
        defineAmberImproperTorsion(class1,
                                   class2,
                                   class3,
                                   class4,
                                   periodicity1,
                                   amp1InKcal * DuMM::Kcal2KJ,
                                   phase1InDegrees,
                                   periodicity2,
                                   amp2InKcal * DuMM::Kcal2KJ,
                                   phase2InDegrees);
    }

    /** Provide three torsion terms in KA units, using kilocalories/mole for
    amplitude. **/
    void defineAmberImproperTorsion_KA(DuMM::AtomClassIndex class1,
                                       DuMM::AtomClassIndex class2,
                                       DuMM::AtomClassIndex class3,
                                       DuMM::AtomClassIndex class4,
                                       int periodicity1,
                                       Real amp1InKcal,
                                       Real phase1InDegrees,
                                       int periodicity2,
                                       Real amp2InKcal,
                                       Real phase2InDegrees,
                                       int periodicity3,
                                       Real amp3InKcal,
                                       Real phase3InDegrees) {
        defineAmberImproperTorsion(class1,
                                   class2,
                                   class3,
                                   class4,
                                   periodicity1,
                                   amp1InKcal * DuMM::Kcal2KJ,
                                   phase1InDegrees,
                                   periodicity2,
                                   amp2InKcal * DuMM::Kcal2KJ,
                                   phase2InDegrees,
                                   periodicity3,
                                   amp3InKcal * DuMM::Kcal2KJ,
                                   phase3InDegrees);
    }

    /** @name               Computational options
    These methods control how DuMM performs its computations. **/
    /**@{**/

    /** For debugging, you can ask DuMM to dump some information to std::clog
    about its attempts to figure out the best way to use the available
    hardware. **/
    void setTracing(bool);

    // Needed in Gmolmodel
    void updateOpenMMPositionsFromState(const State& state) const;

    static void evaluateEnergiesFromState(SimTK::Real& newPotentialEnergy, SimTK::Real& newKineticEnergy);

    [[nodiscard]] static auto integrateTrajectoryWithOpenMM(int steps, SimTK::Real timeStepInPicoseconds)
        -> bool;

    /** How many times has the forcefield been evaluated? **/
    long long getForceEvaluationCount() const;

    /** Produce an ugly but comprehensive dump of the contents of DuMM's internal
    data structures, sent to std::cout (stdout). **/
    void dump() const;

    /** Load test parameters. **/
    // void loadTestMoleculeParameters();

    /**@}**/

    /// OBSOLETE NAME -- just use setTracing().
    void setTraceOpenMM(bool shouldTrace) {
        setTracing(shouldTrace);
    }

    protected:
    /** @cond **/ // don't let doxygen see these
    SimTK_PIMPL_DOWNCAST(DuMMForceFieldSubsystem, ForceSubsystem);
    SimTK_PIMPL_DOWNCAST(DuMMForceFieldSubsystem, Subsystem);
    /** @endcond **/

    void
    defineIncompleteAtomClass(DuMM::AtomClassIndex classIx, const char* name, int elementNumber, int valence);

    void defineIncompleteAtomClass_KA(DuMM::AtomClassIndex classIx,
                                      const char* name,
                                      int elementNumber,
                                      int valence) {
        defineIncompleteAtomClass(classIx, name, elementNumber, valence);
    }

    void setAtomClassVdwParameters(DuMM::AtomClassIndex atomClassIx,
                                   Real vdwRadiusInNm,
                                   Real vdwWellDepthInKJPerMol);
    void
    setAtomClassVdwParameters_KA(DuMM::AtomClassIndex atomClassIx, Real radiusInAng, Real wellDepthInKcal) {
        setAtomClassVdwParameters(atomClassIx, radiusInAng * DuMM::Ang2Nm, wellDepthInKcal * DuMM::Kcal2KJ);
    }

    [[nodiscard]] auto isValidAtomClass(DuMM::AtomClassIndex atomClassIx) const -> bool;

    void defineIncompleteChargedAtomType(DuMM::ChargedAtomTypeIndex chargedAtomTypeIndex,
                                         const char* typeName,
                                         DuMM::AtomClassIndex atomClassIx);

    void defineIncompleteChargedAtomType_KA(DuMM::ChargedAtomTypeIndex chargedAtomTypeIndex,
                                            const char* typeName,
                                            DuMM::AtomClassIndex atomClassIx) {
        defineIncompleteChargedAtomType(chargedAtomTypeIndex, typeName, atomClassIx);
    }

    void setChargedAtomTypeCharge(DuMM::ChargedAtomTypeIndex, Real charge);
    void setChargedAtomTypeCharge_KA(DuMM::ChargedAtomTypeIndex chargedAtomTypeIx, Real charge) {
        setChargedAtomTypeCharge(chargedAtomTypeIx, charge);
    }

    private:
    [[nodiscard]] auto updRep() -> class DuMMForceFieldSubsystemRep&;
    [[nodiscard]] auto getRep() const -> const DuMMForceFieldSubsystemRep&;

    // Indexed by atom index, gives cluster and atom placement index for that atom
    std::vector<DuMM::ClusterIndex> dAIxToClusterIndex;
    std::vector<std::size_t> dAIxToAtomPlacementIx;
    std::vector<DuMM::ClusterIndex> mbxToClusterIndex;

    friend class MolecularMechanicsSystem;
};

