// Class to help manage indexing atoms, subcompounds, and bond centers
class CompoundPathName {
    public:
    static bool isValidTokenName(const String& path) {
        // no empty strings allowed
        if (path.size() == 0) {
            return false;
        }

        for (int c = 0; c < (int)path.size(); ++c) {
            const char& ch = (const char&)path[c];

            // No "/" separator characters allowed in token name
            if ('/' == ch) {
                return false;
            }

            // Space characters are OK...
            // if ( ! isalnum(path[c]) ) return false;
        }

        return true;
    }

    static bool isValidAtomName(const String& path) {
        return isValidTokenName(path);
    }

    static bool isValidSubcompoundName(const String& path) {
        return isValidTokenName(path);
    }

    static bool isValidBondCenterName(const String& path) {
        return isValidTokenName(path);
    }

    // Return the path with the left component removed
    static String shiftLeftPathName(const String& path) {
        int start = (int)path.find_first_of("/");

        ++start; // step past "/" character
                 // std::cout << "CompundAtom path=" << path << "  start=" << start << std::endl;

        assert(start < (int)path.size());

        return path.substr(start);
    }

    // Take pathname of the form xxx/yyy/zzz, check its validity and optionally
    // return as a list of separate subsystem names. We return true if we're successful,
    // false if the pathname is malformed in some way. In that case the last segment
    // returned will be the one that caused trouble.
    static bool isValidSubcompoundPathName(const String& pathname, std::vector<String>* segments) {
        String t;
        const int end = (int)pathname.size();
        int nxt = 0;
        if (segments) {
            segments->clear();
        }
        bool foundAtLeastOne = false;
        // for each segment
        while (nxt < end) {
            // for each character of a segment
            while (nxt < end && pathname[nxt] != '/') {
                t += pathname[nxt++];
            }
            foundAtLeastOne = true;
            if (segments) {
                segments->push_back(t);
            }
            if (!isValidTokenName(t)) {
                return false;
            }
            t.clear();
            ++nxt; // skip '/' (or harmless extra increment at end)
        }
        return foundAtLeastOne;
    }
};


class Bond {
    public:
    Bond()
        : // amRotatable(true),
        mobility(BondMobility::Default)
        , amRingClosingBond(false) {
    }

    Bond(mdunits::Length l, Angle t, bool isRingClosing)
        : defaultDihedral(t)
        , defaultLength(l)
        ,
        // amRotatable(true),
        mobility(BondMobility::Default)
        , amRingClosingBond(isRingClosing) {
    }

    bool isRingClosingBond() const {
        return amRingClosingBond;
    }

    Bond& setRingClosingBond(bool b) {
        amRingClosingBond = b;
        return *this;
    }


    BondMobility::Mobility getMobility() const {
        return mobility;
    }
    Bond& setMobility(BondMobility::Mobility m) {
        mobility = m;
        return *this;
    }

    Bond& setDefaultDihedralAngle(Angle angle) {
        defaultDihedral = angle;
        assert((defaultDihedral >= 0) || (defaultDihedral <= 0));
        return *this;
    }

    Bond& setDihedralAngle(State& state, SimbodyMatterSubsystem& matter, Angle angleInRadians) {
        assert(pinJointId.isValid());

        if (mobility == BondMobility::Torsion) {
            MobilizedBody::Pin& pin = (MobilizedBody::Pin&)matter.updMobilizedBody(pinJointId);
            pin.setAngle(state, angleInRadians);

        } else if (mobility == BondMobility::AnglePin) { // NEWMOB
            // Do nothing
            // MobilizedBody::Pin &anglePin = (MobilizedBody::Pin &) matter.updMobilizedBody(pinJointId);
            // anglePin.setOneQ(state, 0, angleInRadians);

        } else if (mobility == BondMobility::BendStretch) {
        } else if (mobility == BondMobility::Slider) { // NEWMOB
            // Do nothing
            // MobilizedBody::Slider &slider = (MobilizedBody::Slider &) matter.updMobilizedBody(pinJointId);
            // slider.setOneQ(state, 0, length);

        } else if (mobility == BondMobility::Cylinder) { // Gmol
            MobilizedBody::Cylinder& cyl = (MobilizedBody::Cylinder&)matter.updMobilizedBody(pinJointId);
            cyl.setOneQ(state, 0, angleInRadians);

        } else if (mobility == BondMobility::Spherical) { // NEWMOB
            MobilizedBody::SphericalCoords& sphere =
                (MobilizedBody::SphericalCoords&)matter.updMobilizedBody(pinJointId);
            // sphere.setRadialAxis(CoordinateAxis::XCoordinateAxis()); // set translation along X
            // sphere.setNegateRadial(); // common convention for BAT : translation along -Z
            sphere.setOneQ(state, 0, angleInRadians); // azimuth angle

        } else if (mobility == BondMobility::OrthoSpherical) { // NEWMOB NEWMOB
            MobilizedBody::SphericalCoords& sphere =
                (MobilizedBody::SphericalCoords&)matter.updMobilizedBody(pinJointId);
            sphere.setRadialAxis(CoordinateAxis::XCoordinateAxis()); // set translation along X
            sphere.setNegateRadial(true);             // common convention for BAT : translation along -Z
            sphere.setOneQ(state, 0, angleInRadians); // azimuth angle

        } else if ((mobility == BondMobility::BallF) || (mobility == BondMobility::BallM)) { // Gmol NEWMOB

            MobilizedBody::Ball& ball = (MobilizedBody::Ball&)matter.updMobilizedBody(pinJointId);
            ball.setQ(state,
                      SimTK::Rotation(angleInRadians, CoordinateAxis::ZCoordinateAxis())
                          .convertRotationToQuaternion()
                          .asVec4());

        } else if (mobility == BondMobility::UniversalM) { // Gmol NEWMOB

            MobilizedBody::Universal& universal =
                (MobilizedBody::Universal&)matter.updMobilizedBody(pinJointId);
            universal.setQToFitTransform(state,
                                         SimTK::Rotation(angleInRadians, CoordinateAxis::ZCoordinateAxis()));

        } else if ((mobility == BondMobility::LineOrientationF)
                   || (mobility == BondMobility::LineOrientationM)) { // Gmol

            MobilizedBody::LineOrientation& lineOrientation =
                (MobilizedBody::LineOrientation&)matter.updMobilizedBody(pinJointId);
            lineOrientation.setQ(state,
                                 SimTK::Rotation(angleInRadians, CoordinateAxis::ZCoordinateAxis())
                                     .convertRotationToQuaternion()
                                     .asVec4());

        } else if (mobility == BondMobility::Free) { // Gmol
            MobilizedBody::Free& freeB = (MobilizedBody::Free&)matter.updMobilizedBody(pinJointId);
            Vec4 rot = SimTK::Rotation(angleInRadians, CoordinateAxis::ZCoordinateAxis())
                           .convertRotationToQuaternion()
                           .asVec4();
            Vec7 q(rot[0], rot[1], rot[2], rot[3], 0, 0, 0);
            freeB.setQ(state, q);
        }

        return *this;
    }

    Angle getDefaultDihedralAngle() const {
        assert((defaultDihedral >= 0) || (defaultDihedral <= 0));
        return defaultDihedral;
    }

    // Molmodel
    /*    Bond& setPinBody(MobilizedBody::Pin& pin)
        {
            pinJointId = pin.getMobilizedBodyIndex();

            pin.setDefaultAngle(defaultDihedral);
            return *this;
        }*/
    // Molmodel END

    // GMOL BIG RB
    Bond& setPinBody(MobilizedBody::Pin& pin, Angle argDefaultDihedral) {
        pinJointId = pin.getMobilizedBodyIndex();

        pin.setDefaultAngle(argDefaultDihedral);

        return *this;
    }
    // GMOL END

    Bond& setAnglePinBody(MobilizedBody::Pin& pin, Angle argDefaultDihedral) {
        pinJointId = pin.getMobilizedBodyIndex();

        pin.setDefaultAngle(argDefaultDihedral);

        return *this;
    }

    Bond&
    setBendStretchBody(MobilizedBody::BendStretch& cyl, Angle argDefaultDihedral, Real argDefaultLength) {
        pinJointId = cyl.getMobilizedBodyIndex();

        cyl.setDefaultQ(Vec2(argDefaultDihedral, argDefaultLength));

        return *this;
    }

    Bond& setSliderBody(MobilizedBody::Slider& slider, Angle argDefaultLength) {
        pinJointId = slider.getMobilizedBodyIndex();

        slider.setDefaultLength(argDefaultLength);

        return *this;
    }

    // This method does not set default values of Q
    Bond& setCylinderBody(MobilizedBody::Cylinder& cyl, Angle argDefaultDihedral, Real argDefaultLength) {
        pinJointId = cyl.getMobilizedBodyIndex();

        cyl.setDefaultQ(Vec2(argDefaultDihedral, argDefaultLength));

        return *this;
    }

    Bond& setSphericalBody(MobilizedBody::SphericalCoords& sphere,
                           Real argDefaultLength,
                           Angle argDefaultAngle,
                           Angle argDefaultDihedral) {
        pinJointId = sphere.getMobilizedBodyIndex();

        sphere.setDefaultQ(Vec3(argDefaultDihedral, argDefaultAngle, argDefaultLength));

        return *this;
    }

    Bond& setOrthoSphericalBody(MobilizedBody::SphericalCoords& sphere,
                                Real argDefaultLength,
                                Angle argDefaultAngle,
                                Angle argDefaultDihedral) {
        pinJointId = sphere.getMobilizedBodyIndex();

        sphere.setDefaultQ(Vec3(argDefaultDihedral, argDefaultAngle, argDefaultLength));

        return *this;
    }

    Bond& setBallFBody(MobilizedBody::Ball& ball, Angle argDefaultDihedral) {
        pinJointId = ball.getMobilizedBodyIndex();

        SimTK::Rotation R_FM;
        R_FM.setRotationFromAngleAboutX(0.0);
        R_FM.setRotationFromAngleAboutY(0.0);
        R_FM.setRotationFromAngleAboutZ(argDefaultDihedral);

        ball.setDefaultRotation(R_FM);

        return *this;
    }

    Bond& setBallMBody(MobilizedBody::Ball& ball, Angle argDefaultDihedral) {
