    MobilizedBodyIndex getPinJointId() const {
        return pinJointId;
    }

    Angle getDihedralAngle(const State& state, const SimbodyMatterSubsystem& matter) const {
        assert(pinJointId.isValid());

        if (mobility == BondMobility::Torsion) {
            const MobilizedBody::Pin& pin = (const MobilizedBody::Pin&)matter.getMobilizedBody(pinJointId);
            return pin.getAngle(state);

        } else if (mobility == BondMobility::AnglePin) {
            return 0;

        } else if (mobility == BondMobility::Slider) {
            return 0;

        } else if (mobility == BondMobility::Free) {
            const MobilizedBody::Free& free = (const MobilizedBody::Free&)matter.getMobilizedBody(pinJointId);
            Vec7 q7 = free.getQ(state);
            Vec4 q = SimTK::Quaternion(q7[0], q7[1], q7[2], q7[3]);

            double psi;
            // Deal with singularity
            if ((std::abs((q[1] * q[2]) + (q[3] * q[0])) - 0.5) < 0.01) {
                psi = 0.0;
            } else {
                double q0q3 = q[0] * q[3];
                double q1q2 = q[1] * q[2];
                double q2sq = q[2] * q[2];
                double q3sq = q[3] * q[3];
                psi = atan2(2 * (q0q3 + q1q2), 1 - 2 * (q2sq + q3sq));
            }
            return (Angle)psi;


        } else if (mobility == BondMobility::Cylinder) {
            const MobilizedBody::Cylinder& cyl =
                (const MobilizedBody::Cylinder&)matter.getMobilizedBody(pinJointId);
            return cyl.getOneQ(state, 0);

        } else if (mobility == BondMobility::BendStretch) {
            const MobilizedBody::BendStretch& cyl =
                (const MobilizedBody::BendStretch&)matter.getMobilizedBody(pinJointId);
            return cyl.getOneQ(state, 0);

        } else if (mobility == BondMobility::Spherical) {
            const MobilizedBody::SphericalCoords& sphere =
                (const MobilizedBody::SphericalCoords&)matter.getMobilizedBody(pinJointId);
            return (sphere.getQ(state))[0];

        } else if (mobility == BondMobility::OrthoSpherical) {
            const MobilizedBody::SphericalCoords& sphere =
                (const MobilizedBody::SphericalCoords&)matter.getMobilizedBody(pinJointId);
            return (sphere.getQ(state))[0];

        } else if (mobility == BondMobility::UniversalM) {
            const MobilizedBody::Universal& universal =
                (const MobilizedBody::Universal&)matter.getMobilizedBody(pinJointId);
            return universal.getOneQ(state, 0);

        } else if ((mobility == BondMobility::BallF) || (mobility == BondMobility::BallM)) { // Gmol NEWMOB

            const MobilizedBody::Ball& ball = (const MobilizedBody::Ball&)matter.getMobilizedBody(pinJointId);

            // Return psi Euler angle and ignore phi and theta
            Vec4 q = SimTK::Quaternion(ball.getQ(state));
            double psi;
            // Deal with singularity
            if ((std::abs((q[1] * q[2]) + (q[3] * q[0])) - 0.5) < 0.01) {
                psi = 0.0;
            } else {
                double q0q3 = q[0] * q[3];
                double q1q2 = q[1] * q[2];
                double q2sq = q[2] * q[2];
                double q3sq = q[3] * q[3];
                psi = atan2(2 * (q0q3 + q1q2), 1 - 2 * (q2sq + q3sq));
            }
            return (Angle)psi;

        } else if ((mobility == BondMobility::LineOrientationF)
                   || (mobility == BondMobility::LineOrientationM)) { // Gmol

            const MobilizedBody::LineOrientation& lineOrientation =
                (const MobilizedBody::LineOrientation&)matter.getMobilizedBody(pinJointId);

            // Return psi Euler angle and ignore phi and theta
            Vec4 q = SimTK::Quaternion(lineOrientation.getQ(state));
            double psi;
            // Deal with singularity
            if ((std::abs((q[1] * q[2]) + (q[3] * q[0])) - 0.5) < 0.01) {
                psi = 0.0;
            } else {
                double q0q3 = q[0] * q[3];
                double q1q2 = q[1] * q[2];
                double q2sq = q[2] * q[2];
                double q3sq = q[3] * q[3];
                psi = atan2(2 * (q0q3 + q1q2), 1 - 2 * (q2sq + q3sq));
            }
            return (Angle)psi;
        }

        // Shouldn't get here but compiler keeps complaining
        assert(false);
        return 0;
    }

    // GMOL
    Rotation getDefaultRotation(const State& state, const SimbodyMatterSubsystem& matter) const {
        assert(pinJointId.isValid());
        // assert(mobility == BondMobility::BallF);
        // const MobilizedBody::BallF &ball = (const MobilizedBody::BallF &)
        // matter.getMobilizedBody(pinJointId); return ball.getBodyRotation(state);
        return matter.getMobilizedBody(pinJointId).getBodyRotation(state);
    }

    Bond& setDefaultBondLength(mdunits::Length d) {
        defaultLength = d;
        return *this;
    }

    mdunits::Length getDefaultBondLength() const {
        return defaultLength;
    }

    // This transform is symmetric, so it does not matter which bondCenterIsRelative to which
    Transform getDefaultBondCenterFrameInOtherBondCenterFrame() const {
        // std::cout<<__FILE__<<":"<<__LINE__<<std::endl;
        //  1) rotate about x-axis by dihedral angle
        Transform dihedral(Rotation(getDefaultDihedralAngle(), XAxis));

        // 2) translate along x-axis by bond length
        Transform bondLength(Vec3(defaultLength, 0, 0));

        // 3) rotate 180 degrees about y-axis to face the parent bond center
        Transform aboutFace(Rotation(180 * Deg2Rad, YAxis));

        Transform BC1_X_BC2 = dihedral * bondLength * aboutFace;
        // std::cout<<__FILE__<<":"<<__LINE__<<std::endl;

        // throw std::runtime_error("getDefaultBondCenterFrameInOtherBondCenterFrame not implemented yet");

        return BC1_X_BC2;
    }

    Angle getDefaultDihedral() const {
        return defaultDihedral;
    }

    private:
    Angle defaultDihedral;
    mdunits::Length defaultLength;

    // bool amRotatable;
    BondMobility::Mobility mobility;

    bool amRingClosingBond;

    MobilizedBodyIndex pinJointId;
};


