                       (int)class4);
    SimTK_APIARGCHECK(periodicity1 != -1 || periodicity2 != -1 || periodicity3 != -1 || periodicity4 != -1
                          || periodicity5 != -1,
                      ApiClassName,
                      CallingMethodName,
                      "must be at least one torsion term supplied");

    if (periodicity1 != -1) {
