auto DuMMForceFieldSubsystem::updAllAtomStation(DuMM::AtomIndex dAIx) -> Vec3& {
    static const char* MethodName = "getAtomStationOnBody";
    DuMMForceFieldSubsystemRep& rep = updRep();

