class Element::Impl // : public PIMPLImplementation<Element,ElementRep> 
{
public:
    Impl* clone() const {return new Impl(*this);}

    Impl()
        : atomicNumber(Element::InvalidAtomicNumber)
    {}

    Impl(int an, Element::Name nm, Element::Symbol sm, mdunits::Mass ms)
        : symbol(sm), name(nm), averageMass(ms), atomicNumber(an)
    {}

    Element::Symbol getSymbol() const {return symbol;}
	int getAtomicNumber() const {return atomicNumber;}
    Element::Name   getName() const {return name;}
    mdunits::Mass getMass() const {return averageMass;}

private:
    Element::Symbol symbol;
    Element::Name name;
    // Average mass is used, as opposed to typical mass
    mdunits::Mass averageMass;
    int atomicNumber;
};

