        //     const Transform& X_BM = getDefaultOutboardFrame(); // TODO: get from state
        //     if (X_BM.p() != Vec3(0) || X_BM.R() != Mat33(1)) {
        //         DecorativeFrame frameOnChild(scale / 4);
        //         frameOnChild.setBodyId(myMobilizedBodyIndex);
        //         frameOnChild.setColor(Red);
