/////////////////////////////////////////////////
// MOBILIZED BODY::CUSTOM::IMPLEMENTATION IMPL //
/////////////////////////////////////////////////

// This class exists primarily to allow the Custom::Implementation class to keep
// a pointer to its handle class's CustomImpl class which is derived from MobilizedBodyImpl
// which has all the goodies that are needed for defining a MobilizedBody.
//
// At first this class is the owner of the CustomImpl. Then when this is put in a
// Custom handle, that handle takes over ownership of the CustomImpl and the
// CustomImpl takes over ownership of this ImplementationImpl object.
class MobilizedBody::Custom::ImplementationImpl
    : public PIMPLImplementation<Implementation, ImplementationImpl> {
    public:
    // no default constructor
    explicit ImplementationImpl(CustomImpl* customImpl, int nu, int nq, int nAngles)
        : isOwner(true)
        , builtInImpl(customImpl)
        , nu(nu)
        , nq(nq)
        , nAngles(nAngles) {
    }
    inline ~ImplementationImpl(); // see below -- have to wait for CustomImpl's definition

    // Copying one of these just gives us a new one with a NULL CustomImpl pointer.
    ImplementationImpl(const ImplementationImpl& src)
        : isOwner(false)
        , builtInImpl(0)
        , nu(src.nu)
        , nq(src.nq)
        , nAngles(src.nAngles) {
    }

    ImplementationImpl* clone() const {
        return new ImplementationImpl(*this);
    }

    bool isOwnerOfCustomImpl() const {
        return builtInImpl && isOwner;
    }
    CustomImpl* removeOwnershipOfCustomImpl() {
        assert(isOwnerOfCustomImpl());
        isOwner = false;
        return builtInImpl;
    }

    void setReferenceToCustomImpl(CustomImpl* cimpl) {
        assert(!builtInImpl); // you can only do this once
        isOwner = false;
        builtInImpl = cimpl;
    }

    bool hasCustomImpl() const {
        return builtInImpl != 0;
    }

    const CustomImpl& getCustomImpl() const {
        assert(builtInImpl);
        return *builtInImpl;
    }
    CustomImpl& updCustomImpl() {
        assert(builtInImpl);
        return *builtInImpl;
    }

    int getNU() const {
        return nu;
    }

    int getNQ() const {
        return nq;
    }

    int getNumAngles() const {
        return nAngles;
    }

    private:
    bool isOwner;
    CustomImpl* builtInImpl; // just a reference; not owned
    int nu, nq, nAngles;

    // suppress assignment
    ImplementationImpl& operator=(const ImplementationImpl&);
};

/////////////////////////////////
// MOBILIZED BODY::CUSTOM IMPL //
/////////////////////////////////

class MobilizedBody::CustomImpl : public MobilizedBodyImpl {
    public:
    explicit CustomImpl(Direction d)
        : MobilizedBodyImpl(d)
        , implementation(0) {
    }

    void takeOwnershipOfImplementation(Custom::Implementation* userImpl);

    explicit CustomImpl(Custom::Implementation* userImpl, Direction d)
        : MobilizedBodyImpl(d)
        , implementation(0) {
        assert(userImpl);
        implementation = userImpl;
        implementation->updImpl().setReferenceToCustomImpl(this);
    }

    // Copy constructor
    CustomImpl(const CustomImpl& src)
        : MobilizedBodyImpl(src)
        , implementation(0) {
        if (src.implementation) {
            implementation = src.implementation->clone();
            implementation->updImpl().setReferenceToCustomImpl(this);
        }
    }

    ~CustomImpl() {
        if (implementation) {
            delete implementation;
        }
    }

    CustomImpl* clone() const override {
        return new CustomImpl(*this);
    }

    const Custom::Implementation& getImplementation() const {
        assert(implementation);
        return *implementation;
    }

    Custom::Implementation& updImplementation() {
        assert(implementation);
        return *implementation;
    }

    RigidBodyNode*
    createRigidBodyNode(UIndex& nextUSlot, USquaredIndex& nextUSqSlot, QIndex& nextQSlot) const override;

    void copyOutDefaultQImpl(int nq, Real* q) const override {
        SimTK_ASSERT(nq == getImplementation().getImpl().getNQ()
                         || nq == getImplementation().getImpl().getNQ() - 1,
                     "MobilizedBody::CustomImpl::copyOutDefaultQImpl(): wrong number of q's");
        for (int i = 0; i < nq; ++i) {
            q[i] = 0.0;
        }
        if (implementation->getImpl().getNumAngles() == 4) {
            q[0] = 1.0;
        }
    }

    // Forward all the virtuals to the Custom::Implementation virtuals.
    void realizeTopologyVirtual(State& s) const override {
        getImplementation().realizeTopology(s);
    }
    void realizeModelVirtual(State& s) const override {
        getImplementation().realizeModel(s);
    }
    void realizeInstanceVirtual(const State& s) const override {
        getImplementation().realizeInstance(s);
    }
    void realizeTimeVirtual(const State& s) const override {
        getImplementation().realizeTime(s);
    }
    void realizePositionVirtual(const State& s) const override {
        getImplementation().realizePosition(s);
    }
    void realizeVelocityVirtual(const State& s) const override {
        getImplementation().realizeVelocity(s);
    }
    void realizeDynamicsVirtual(const State& s) const override {
        getImplementation().realizeDynamics(s);
    }
    void realizeAccelerationVirtual(const State& s) const override {
        getImplementation().realizeAcceleration(s);
    }
    void realizeReportVirtual(const State& s) const override {
        getImplementation().realizeReport(s);
    }

    void
    calcDecorativeGeometryAndAppend(const State& s, Stage stage, Array_<DecorativeGeometry>& geom) const {
        getImplementation().calcDecorativeGeometryAndAppend(s, stage, geom);
    }

    SimTK_DOWNCAST(CustomImpl, MobilizedBodyImpl);

    private:
    friend class MobilizedBody::Custom;

    Custom::Implementation* implementation;

    CustomImpl& operator=(const CustomImpl&); // suppress assignment
};

// Need definition for CustomImpl here in case we have to delete it.
inline MobilizedBody::Custom::ImplementationImpl::~ImplementationImpl() {
    if (isOwner) {
        delete builtInImpl;
    }
    builtInImpl = 0;
}

////////////////////////////////////////
// MOBILIZED BODY::FUNCTIONBASED IMPL //
////////////////////////////////////////


class MobilizedBody::FunctionBasedImpl : public MobilizedBody::Custom::Implementation {
    public:
    // Constructor that uses default axes
    FunctionBasedImpl(SimbodyMatterSubsystem& matter,
                      int nmobilities,
                      const Array_<const Function*>& functions,
                      const Array_<Array_<int>>& coordIndices)
        : Implementation(matter, nmobilities, nmobilities, 0)
        , subsystem(matter.getMySubsystemIndex())
        , nu(nmobilities)
        , cacheIndex(0)
        , functions(functions)
        , coordIndices(coordIndices)
        , referenceCount(new int[1]) {
        assert(functions.size() == 6);
        assert(coordIndices.size() == 6);
        referenceCount[0] = 1;
        for (int i = 0; i < (int)functions.size(); ++i) {
            assert(functions[i]->getArgumentSize() == coordIndices[i].size());
            assert(functions[i]->getMaxDerivativeOrder() >= 2);
        }
        Arot = Mat33(1);
        Atrans = Mat33(1);
    }
    FunctionBasedImpl(SimbodyMatterSubsystem& matter,
                      int nmobilities,
                      const Array_<const Function*>& functions,
                      const Array_<Array_<int>>& coordIndices,
                      const Array_<Vec3>& axes)
        : Implementation(matter, nmobilities, nmobilities, 0)
        , subsystem(matter.getMySubsystemIndex())
        , nu(nmobilities)
        , cacheIndex(0)
        , functions(functions)
        , coordIndices(coordIndices)
        , referenceCount(new int[1]) {
        assert(functions.size() == 6);
        assert(coordIndices.size() == 6);
        assert(axes.size() == 6);
        referenceCount[0] = 1;
        for (int i = 0; i < (int)functions.size(); ++i) {
            assert(functions[i]->getArgumentSize() == coordIndices[i].size());
            assert(functions[i]->getMaxDerivativeOrder() >= 2);
        }
        double tol = 1e-5;
        // Verify that none of the rotation axes are colinear
        assert((axes[0] % axes[1]).norm() > tol);
        assert((axes[0] % axes[2]).norm() > tol);
        assert((axes[1] % axes[2]).norm() > tol);
        // Verify that none of the translational axes are colinear
        assert((axes[3] % axes[4]).norm() > tol);
        assert((axes[3] % axes[5]).norm() > tol);
        assert((axes[4] % axes[5]).norm() > tol);

        Arot = Mat33(axes[0].normalize(), axes[1].normalize(), axes[2].normalize());
        Atrans = Mat33(axes[3].normalize(), axes[4].normalize(), axes[5].normalize());
    }

    ~FunctionBasedImpl() {
        if (--referenceCount[0] == 0) {
            for (int i = 0; i < (int)functions.size(); i++) {
                delete functions[i];
            }
            delete[] referenceCount;
        }
    }

    MobilizedBody::Custom::Implementation* clone() const override {
        referenceCount[0]++;
        return new FunctionBasedImpl(*this);
    }

    Transform calcMobilizerTransformFromQ(const State& s, int nq, const Real* q) const override {
        // Initialize the tranformation to be returned
        Transform X(Vec3(0));
        Vec6 spatialCoords;

        // Get the spatial cooridinates as a function of the q's
        for (int i = 0; i < 6; i++) {
            // Coordinates for this function
            int nc = coordIndices[i].size();
            Vector fcoords(nc);

            for (int j = 0; j < nc; j++) {
                fcoords(j) = q[coordIndices[i][j]];
            }

            // default behavior of constant function should take a Vector of length 0
            spatialCoords(i) = functions[i]->calcValue(fcoords);
        }

        /*
                UnitVec3 axis1;
                axis1.getAs(&Arot(0,0));
                UnitVec3 axis2;
                axis2.getAs(&Arot(0,1));
                UnitVec3 axis3;
                axis3.getAs(&Arot(0,2));
        */

        // X.updR().setRotationToBodyFixedXYZ(spatialCoords.getSubVec<3>(0));
        X.updR().setRotationFromMat33TrustMe(Rotation(spatialCoords(0), UnitVec3::getAs(&Arot(0, 0)))
                                             * Rotation(spatialCoords(1), UnitVec3::getAs(&Arot(0, 1)))
                                             * Rotation(spatialCoords(2), UnitVec3::getAs(&Arot(0, 2))));
        X.updP() = spatialCoords(3) * UnitVec3::getAs(&Atrans(0, 0))
                   + spatialCoords(4) * UnitVec3::getAs(&Atrans(0, 1))
                   + spatialCoords(5) * UnitVec3::getAs(&Atrans(0, 2));

        return X;
    }

    SpatialVec multiplyByHMatrix(const State& s, int nu, const Real* u) const override {
        switch (nu) {
            case 1: {
                // Check that the H  matrices in the cache are valid
                if (!(Value<CacheInfo<1>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidH)) {
                    updateH(s);
                }

                Mat<2, 1, Vec3> h =
                    Value<CacheInfo<1>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().h;
                return h * Vec1::getAs(u);
            }
            case 2: {
                // Check that the H  matrices in the cache are valid
                if (!(Value<CacheInfo<2>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidH)) {
                    updateH(s);
                }

                Mat<2, 2, Vec3> h =
                    Value<CacheInfo<2>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().h;
                return h * Vec2::getAs(u);
            }
            case 3: {
                // Check that the H  matrices in the cache are valid
                if (!(Value<CacheInfo<3>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidH)) {
                    updateH(s);
                }

                Mat<2, 3, Vec3> h =
                    Value<CacheInfo<3>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().h;
                return h * Vec3::getAs(u);
            }
            case 4: {
                // Check that the H  matrices in the cache are valid
                if (!(Value<CacheInfo<4>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidH)) {
                    updateH(s);
                }

                Mat<2, 4, Vec3> h =
                    Value<CacheInfo<4>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().h;
                return h * Vec4::getAs(u);
            }
            case 5: {
                // Check that the H matrices in the cache are valid
                if (!(Value<CacheInfo<5>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidH)) {
                    updateH(s);
                }

                Mat<2, 5, Vec3> h =
                    Value<CacheInfo<5>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().h;
                return h * Vec5::getAs(u);
            }
            case 6: {
                // Check that the H  matrices in the cache are valid
                if (!(Value<CacheInfo<6>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidH)) {
                    updateH(s);
                }

                Mat<2, 6, Vec3> h =
                    Value<CacheInfo<6>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().h;
                return h * Vec6::getAs(u);
            }
        }
        SimTK_THROW5(SimTK::Exception::ValueOutOfRange,
                     "nu",
                     1,
                     nu,
                     6,
                     "MobilizedBody::FunctionBasedImpl::multiplyByHMatrix");
    }

    void multiplyByHTranspose(const State& s, const SpatialVec& F, int nu, Real* f) const override {
        switch (nu) {
            case 1: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<1>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidH)) {
                    updateH(s);
                }

                Mat<2, 1, Vec3> h =
                    Value<CacheInfo<1>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().h;
                Vec1::updAs(f) = ~h * F;
                return;
            }
            case 2: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<2>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidH)) {
                    updateH(s);
                }

                Mat<2, 2, Vec3> h =
                    Value<CacheInfo<2>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().h;
                Vec2::updAs(f) = ~h * F;
                return;
            }
            case 3: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<3>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidH)) {
                    updateH(s);
                }

                Mat<2, 3, Vec3> h =
                    Value<CacheInfo<3>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().h;
                Vec3::updAs(f) = ~h * F;
                return;
            }
            case 4: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<4>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidH)) {
                    updateH(s);
                }

                Mat<2, 4, Vec3> h =
                    Value<CacheInfo<4>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().h;
                Vec4::updAs(f) = ~h * F;
                return;
            }
            case 5: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<5>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidH)) {
                    updateH(s);
                }

                Mat<2, 5, Vec3> h =
                    Value<CacheInfo<5>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().h;
                Vec5::updAs(f) = ~h * F;
                return;
            }
            case 6: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<6>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidH)) {
                    updateH(s);
                }

                Mat<2, 6, Vec3> h =
                    Value<CacheInfo<6>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().h;
                Vec6::updAs(f) = ~h * F;
                return;
            }
        }
        SimTK_THROW5(SimTK::Exception::ValueOutOfRange,
                     "nu",
                     1,
                     nu,
                     6,
                     "MobilizedBody::FunctionBasedImpl::multiplyByHTranspose");
    }

    SpatialVec multiplyByHDotMatrix(const State& s, int nu, const Real* u) const override {
        switch (nu) {
            case 1: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<1>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidHdot)) {
                    updateHdot(s);
                }

                Mat<2, 1, Vec3> hdot =
                    Value<CacheInfo<1>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().hdot;
                return hdot * Vec1::getAs(u);
            }
            case 2: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<2>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidHdot)) {
                    updateHdot(s);
                }

                Mat<2, 2, Vec3> hdot =
                    Value<CacheInfo<2>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().hdot;
                return hdot * Vec2::getAs(u);
            }
            case 3: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<3>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidHdot)) {
                    updateHdot(s);
                }

                Mat<2, 3, Vec3> hdot =
                    Value<CacheInfo<3>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().hdot;
                return hdot * Vec3::getAs(u);
            }
            case 4: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<4>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidHdot)) {
                    updateHdot(s);
                }

                Mat<2, 4, Vec3> hdot =
                    Value<CacheInfo<4>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().hdot;
                return hdot * Vec4::getAs(u);
            }
            case 5: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<5>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidHdot)) {
                    updateHdot(s);
                }

                Mat<2, 5, Vec3> hdot =
                    Value<CacheInfo<5>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().hdot;
                return hdot * Vec5::getAs(u);
            }
            case 6: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<6>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidHdot)) {
                    updateHdot(s);
                }

                Mat<2, 6, Vec3> hdot =
                    Value<CacheInfo<6>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().hdot;
                return hdot * Vec6::getAs(u);
            }
        }
        SimTK_THROW5(SimTK::Exception::ValueOutOfRange,
                     "nu",
                     1,
                     nu,
                     6,
                     "MobilizedBody::FunctionBasedImpl::multiplyByHDotMatrix");
    }

    void multiplyByHDotTranspose(const State& s, const SpatialVec& F, int nu, Real* f) const override {
        switch (nu) {
            case 1: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<1>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidHdot)) {
                    updateHdot(s);
                }

                Mat<2, 1, Vec3> hdot =
                    Value<CacheInfo<1>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().hdot;
                Vec1::updAs(f) = ~hdot * F;
                return;
            }
            case 2: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<2>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidHdot)) {
                    updateHdot(s);
                }

                Mat<2, 2, Vec3> hdot =
                    Value<CacheInfo<2>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().hdot;
                Vec2::updAs(f) = ~hdot * F;
                return;
            }
            case 3: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<3>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidHdot)) {
                    updateHdot(s);
                }

                Mat<2, 3, Vec3> hdot =
                    Value<CacheInfo<3>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().hdot;
                Vec3::updAs(f) = ~hdot * F;
                return;
            }
            case 4: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<4>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidHdot)) {
                    updateHdot(s);
                }

                Mat<2, 4, Vec3> hdot =
                    Value<CacheInfo<4>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().hdot;
                Vec4::updAs(f) = ~hdot * F;
                return;
            }
            case 5: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<5>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidHdot)) {
                    updateHdot(s);
                }

                Mat<2, 5, Vec3> hdot =
                    Value<CacheInfo<5>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().hdot;
                Vec5::updAs(f) = ~hdot * F;
                return;
            }
            case 6: {
                // Check that the H and Hdot matrices in the cache are valid
                if (!(Value<CacheInfo<6>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex))
                          .upd()
                          .isValidHdot)) {
                    updateHdot(s);
                }

                Mat<2, 6, Vec3> hdot =
                    Value<CacheInfo<6>>::downcast(s.getCacheEntry(subsystem, cacheIndex)).get().hdot;
                Vec6::updAs(f) = ~hdot * F;
                return;
            }
        }
        SimTK_THROW5(SimTK::Exception::ValueOutOfRange,
                     "nu",
                     1,
                     nu,
                     6,
                     "MobilizedBody::FunctionBasedImpl::multiplyByHDotTranspose");
    }

    void realizeTopology(State& s) const override {
        switch (nu) {
            case 1:
                cacheIndex = s.allocateCacheEntry(subsystem, Stage::Topology, new Value<CacheInfo<1>>());
                break;
            case 2:
                cacheIndex = s.allocateCacheEntry(subsystem, Stage::Topology, new Value<CacheInfo<2>>());
                break;
            case 3:
                cacheIndex = s.allocateCacheEntry(subsystem, Stage::Topology, new Value<CacheInfo<3>>());
                break;
            case 4:
                cacheIndex = s.allocateCacheEntry(subsystem, Stage::Topology, new Value<CacheInfo<4>>());
                break;
            case 5:
                cacheIndex = s.allocateCacheEntry(subsystem, Stage::Topology, new Value<CacheInfo<5>>());
                break;
            case 6:
                cacheIndex = s.allocateCacheEntry(subsystem, Stage::Topology, new Value<CacheInfo<6>>());
                break;
        }
    }

    void realizePosition(const State& s) const override {
        switch (nu) {
            case 1: {
                // invalidate H and Hdot matrices
                Value<CacheInfo<1>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd().isValidH =
                    false;
                break;
            }
            case 2: {
                // invalidate H and Hdot matrices
                Value<CacheInfo<2>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd().isValidH =
                    false;
                break;
            }
            case 3: {
                // invalidate H and Hdot matrices
                Value<CacheInfo<3>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd().isValidH =
                    false;
                break;
            }
            case 4: {
                // invalidate H and Hdot matrices
                Value<CacheInfo<4>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd().isValidH =
                    false;
                break;
            }
            case 5: {
                // invalidate H and Hdot matrices
                Value<CacheInfo<5>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd().isValidH =
                    false;
                break;
            }
            case 6: {
                // invalidate H and Hdot matrices
                Value<CacheInfo<6>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd().isValidH =
                    false;
                break;
            }
        }
    }

    void realizeVelocity(const State& s) const override {
        switch (nu) {
            case 1: {
                // invalidate H and Hdot matrices
                Value<CacheInfo<1>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd().isValidHdot =
                    false;
                break;
            }
            case 2: {
                // invalidate H and Hdot matrices
                Value<CacheInfo<2>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd().isValidHdot =
                    false;
                break;
            }
            case 3: {
                // invalidate H and Hdot matrices
                Value<CacheInfo<3>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd().isValidHdot =
                    false;
                break;
            }
            case 4: {
                // invalidate H and Hdot matrices
                Value<CacheInfo<4>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd().isValidHdot =
                    false;
                break;
            }
            case 5: {
                // invalidate H and Hdot matrices
                Value<CacheInfo<5>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd().isValidHdot =
                    false;
                break;
            }
            case 6: {
                // invalidate H and Hdot matrices
                Value<CacheInfo<6>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd().isValidHdot =
                    false;
                break;
            }
        }
    }

    void updateH(const State& s) const {
        // Get mobilizer kinematics
        Vector q = getQ(s);
        Vector u = getU(s);
        switch (nu) {
            case 1: {
                CacheInfo<1>& cache =
                    Value<CacheInfo<1>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd();
                cache.buildH(q, u, getMobilizerTransform(s), functions, coordIndices, Arot, Atrans);
                // H matrix is now valid
                cache.isValidH = true;
                break;
            }
            case 2: {
                CacheInfo<2>& cache =
                    Value<CacheInfo<2>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd();
                cache.buildH(q, u, getMobilizerTransform(s), functions, coordIndices, Arot, Atrans);
                // H matrix is now valid
                cache.isValidH = true;
                break;
            }
            case 3: {
                CacheInfo<3>& cache =
                    Value<CacheInfo<3>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd();
                cache.buildH(q, u, getMobilizerTransform(s), functions, coordIndices, Arot, Atrans);
                // H matrix is now valid
                cache.isValidH = true;
                break;
            }
            case 4: {
                CacheInfo<4>& cache =
                    Value<CacheInfo<4>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd();
                cache.buildH(q, u, getMobilizerTransform(s), functions, coordIndices, Arot, Atrans);
                // H matrix is now valid
                cache.isValidH = true;
                break;
            }
            case 5: {
                CacheInfo<5>& cache =
                    Value<CacheInfo<5>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd();
                cache.buildH(q, u, getMobilizerTransform(s), functions, coordIndices, Arot, Atrans);
                // H matrix is now valid
                cache.isValidH = true;
                break;
            }
            case 6: {
                CacheInfo<6>& cache =
                    Value<CacheInfo<6>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd();
                cache.buildH(q, u, getMobilizerTransform(s), functions, coordIndices, Arot, Atrans);
                // H matrix is now valid
                cache.isValidH = true;
                break;
            }
        }
    }

    void updateHdot(const State& s) const {
        // Get mobilizer kinematics
        Vector q = getQ(s);
        Vector u = getU(s);
        switch (nu) {
            case 1: {
                CacheInfo<1>& cache =
                    Value<CacheInfo<1>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd();
                cache.buildHdot(q, u, getMobilizerTransform(s), functions, coordIndices, Arot, Atrans);
                // Hdot matrix is now valid
                cache.isValidHdot = true;
                break;
            }
            case 2: {
                CacheInfo<2>& cache =
                    Value<CacheInfo<2>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd();
                cache.buildHdot(q, u, getMobilizerTransform(s), functions, coordIndices, Arot, Atrans);
                // Hdot matrix is now valid
                cache.isValidHdot = true;
                break;
            }
            case 3: {
                CacheInfo<3>& cache =
                    Value<CacheInfo<3>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd();
                cache.buildHdot(q, u, getMobilizerTransform(s), functions, coordIndices, Arot, Atrans);
                // Hdot matrix is now valid
                cache.isValidHdot = true;
                break;
            }
            case 4: {
                CacheInfo<4>& cache =
                    Value<CacheInfo<4>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd();
                cache.buildHdot(q, u, getMobilizerTransform(s), functions, coordIndices, Arot, Atrans);
                // Hdot matrix is now valid
                cache.isValidHdot = true;
                break;
            }
            case 5: {
                CacheInfo<5>& cache =
                    Value<CacheInfo<5>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd();
                cache.buildHdot(q, u, getMobilizerTransform(s), functions, coordIndices, Arot, Atrans);
                // Hdot matrix is now valid
                cache.isValidHdot = true;
                break;
            }
            case 6: {
                CacheInfo<6>& cache =
                    Value<CacheInfo<6>>::updDowncast(s.updCacheEntry(subsystem, cacheIndex)).upd();
                cache.buildHdot(q, u, getMobilizerTransform(s), functions, coordIndices, Arot, Atrans);
                // Hdot matrix is now valid
                cache.isValidHdot = true;
                break;
            }
        }
    }

    private:
    const SubsystemIndex subsystem;
    const int nu;
    mutable CacheEntryIndex cacheIndex;
    const Array_<const Function*> functions;
    const Array_<Array_<int>> coordIndices;
    int* referenceCount;
    // const Array_<Vec3> axes;
    Mat33 Arot, Atrans;
    template <int N>
    class CacheInfo {
        public:
        CacheInfo()
            : isValidH(false)
            , isValidHdot(false) {
        }

        void buildH(Vector& q,
                    Vector& u,
                    const Transform& X_FM,
                    const Array_<const Function*>& functions,
                    const Array_<Array_<int>>& coordIndices,
                    const Mat33 Arot,
                    const Mat33 Atrans) {
            // Build the Fq and Fqq matrices of partials of the spatial functions with respect to the gen
            // coordinates, q Cycle through each row (function describing spatial coordinate)
            Fq = Mat<6, N>(0);
            Vec6 spatialCoords(0);
            Array_<int> deriv(1);
            Vector fcoords(coordIndices[0].size());

            for (int i = 0; i < 6; i++) {
                // Determine the number of coordinates for this function
                int nc = coordIndices[i].size();
                if (fcoords.size() != nc) {
                    fcoords.resize(nc);
                }

                if (nc > 0) {
                    // Get coordinate values to evaluate the function
                    for (int k = 0; k < nc; k++) {
                        fcoords(k) = q(coordIndices[i][k]);
                    }

                    for (int j = 0; j < nc; j++) {
                        deriv[0] = j;
                        Fq(i, coordIndices[i][j]) = functions[i]->calcDerivative(deriv, fcoords);
                    }
                    // default behavior of constant function should take a Vector of length 0
                    spatialCoords(i) = functions[i]->calcValue(fcoords);
                }
            }
            // Note rotations are body fixed sequences, and so taking the derivative yields a body-fixed
            // angular velocity and therefore, must be transformed to the parent frame.

            // omega = [a1, R_F1*a2, R_F2*a3]*{Theta_dot(q)}, where Theta_dot(q) is described by the first
            // three functions
            //       = [W*[Fq_theta]*qdot
            // vel = [A]*{X_dot(q)}, where X_dot(q) is described by the last three functions
            //     = [A]*[Fq_x]*qdot

            Rotation R_F1 = Rotation(spatialCoords(0), UnitVec3::getAs(&Arot(0, 0)));
            Rotation R_F2 = R_F1 * Rotation(spatialCoords(1), UnitVec3::getAs(&Arot(0, 1)));

            Mat31 temp;
            Mat33 W(UnitVec3::getAs(&Arot(0, 0)),
                    R_F1 * (UnitVec3::getAs(&Arot(0, 1))),
                    R_F2 * (UnitVec3::getAs(&Arot(0, 2))));

            for (int i = 0; i < N; i++) {
                temp = W * (Fq.template getSubMat<3, 1>(0, i));
                h(0, i) = Vec3::getAs(&temp(0, 0));
                temp = Atrans * (Fq.template getSubMat<3, 1>(3, i));
                h(1, i) = Vec3::getAs(&temp(0, 0));
            }
        }

        void buildHdot(Vector& q,
                       Vector& u,
                       const Transform& X_FM,
                       const Array_<const Function*>& functions,
                       const Array_<Array_<int>>& coordIndices,
                       const Mat33 Arot,
                       const Mat33 Atrans) {
            Mat<6, N> Fqdot(0);
            Vec6 spatialCoords;
            Array_<int> derivs(2);
            Vector fcoords(coordIndices[0].size());

            for (int i = 0; i < 6; i++) {
                // Determine the number of coordinates for this function
                int nc = coordIndices[i].size();
                if (fcoords.size() != nc) {
                    fcoords.resize(nc);
                }

                if (nc > 0) {
                    // Get coordinate values to evaluate the function
                    for (int k = 0; k < nc; k++) {
                        fcoords(k) = q(coordIndices[i][k]);
                    }

                    // function is dependent on a mobility if its index is in the list of function
                    // coordIndices cycle through the mobilities
                    for (int j = 0; j < nc; j++) {
                        derivs[0] = j;
                        for (int k = 0; k < nc; k++) {
                            derivs[1] = k;
                            Fqdot(i, coordIndices[i][j]) +=
                                functions[i]->calcDerivative(derivs, fcoords) * u[coordIndices[i][k]];
                        }
                    }
                }
                // default behavior of constant function should take a Vector of length 0
                spatialCoords(i) = functions[i]->calcValue(fcoords);
            }

            Rotation R_F1 = Rotation(spatialCoords(0), UnitVec3::getAs(&Arot(0, 0)));
            Rotation R_F2 = R_F1 * Rotation(spatialCoords(1), UnitVec3::getAs(&Arot(0, 1)));

            Mat33 W(UnitVec3::getAs(&Arot(0, 0)),
                    R_F1 * (UnitVec3::getAs(&Arot(0, 1))),
                    R_F2 * (UnitVec3::getAs(&Arot(0, 2))));

            // Hdot_theta = [Wdot]*[Fq] + [W][Fqdot]
            // Hdot_x = [A]*[Fqdot]
            Real* up = &u[0];
            Vec<N> uv = Vec<N>::getAs(up);
            Vec<N> uv1 = uv;
            Vec<N> uv2 = uv;

            for (int i = 1; i < N; i++) {
                uv1(i) = 0;
            }
            if (N > 2) {
                uv2(2) = 0;
            }

            // Spatial velocity
            SpatialVec V = h * uv;
            SpatialVec V1 = h * uv1;
            SpatialVec V2 = h * uv2;
            // First V[0] is angular velocity, omega
            // Mat33 Wdot(Vec3(0), Vec3(V[0](0),0,0)%(Vec3::getAs(&W(0,1))),
            // Vec3(V[0](0),V[0](1),0)%(Vec3::getAs(&W(0,2))));
            Mat33 Wdot(Vec3(0), V1[0] % (Vec3::getAs(&W(0, 1))), V2[0] % (Vec3::getAs(&W(0, 2))));

            // Sanity check Omega == V[0]
            Mat31 Omega = W * (Fq.template getSubMat<3, N>(0, 0)) * (Mat<N, 1>::getAs(up));

            Mat31 temp;
            for (int i = 0; i < N; i++) {
                temp =
                    Wdot * (Fq.template getSubMat<3, 1>(0, i)) + W * (Fqdot.template getSubMat<3, 1>(0, i));
                hdot(0, i) = Vec3::getAs(&temp(0, 0));
                temp = Atrans * (Fqdot.template getSubMat<3, 1>(3, i));
                hdot(1, i) = Vec3::getAs(&temp(0, 0));
            }
        }

        Mat<2, N, Vec3> h, hdot;
        Mat<6, N> Fq;
        bool isValidH;
        bool isValidHdot;
    };
};

