    // BASE CLASS METHODS //


    static RigidBodyNode* createGroundNode();

    // Register the passed-in node as a child of this one.
    void addChild(RigidBodyNode* child);
    void setParent(RigidBodyNode* p) {
        parent = p;
    }
    void setNodeNum(MobilizedBodyIndex n) {
        nodeNum = n;
    }
    void setLevel(int i) {
        level = i;
    }

    // TOPOLOGICAL INFO: no State needed

    RigidBodyNode* getParent() const {
        return parent;
    }
    int getNumChildren() const {
        return (int)children.size();
    }
    RigidBodyNode* getChild(int i) const {
        return (i < (int)children.size() ? children[i] : 0);
    }

    bool isReversed() const {
        return reversed;
    }

    // Return this node's level, that is, how many ancestors separate it from
    // the Ground node at level 0. Level 1 nodes (directly connected to the
    // Ground node) are called 'base' nodes.
    int getLevel() const {
        return level;
    }

    // This is the unique "body index" for this (body,mobilizer) node. It is used to index
    // arrays of body quantities.
    MobilizedBodyIndex getNodeNum() const {
        return nodeNum;
    }

    bool isGroundNode() const {
        return level == 0;
    }
    bool isBaseNode() const {
        return level == 1;
    }

    // TODO: these should come from the model cache.
    UIndex getUIndex() const {
        return uIndex;
    }
    QIndex getQIndex() const {
        return qIndex;
    }


