void RigidBodyNodeSpec<dof, noR_FM, noX_MB, noR_PF>::calcDetMPass2Outward(
    const SBInstanceCache& ic,
    const SBTreePositionCache& pc,
    const SBArticulatedBodyInertiaCache& abc,
