namespace SimTK {


std::ostream& operator<<(std::ostream& o, const RowCol& rc) {
    return o << "(" << rc.row << "," << rc.col << ")";
}

std::ostream& operator<<(std::ostream& o, const NRowCol& s) {
    return o << "[" << s.nrow << "x" << s.ncol << "]";
