}
template <class S>
void MatrixHelper<S>::rowSum(int i, S* const answer) const {
    rep->rowSum(i, answer);
}
template <class S>
void MatrixHelper<S>::fillWithScalar(const typename CNT<S>::StdNumber& s) {
    rep->fillWithScalar(s);
}

template <class S>
bool MatrixHelper<S>::hasContiguousData() const {
    return rep->hasContiguousData();
}
template <class S>
ptrdiff_t MatrixHelper<S>::getContiguousDataLength() const {
    assert(hasContiguousData());
    return rep->nScalars();
}
template <class S>
const S* MatrixHelper<S>::getContiguousData() const {
    assert(hasContiguousData());
    return rep->m_data;
}
template <class S>
S* MatrixHelper<S>::updContiguousData() {
    assert(hasContiguousData());
    return rep->m_data;
}
template <class S>
void MatrixHelper<S>::replaceContiguousData(S* newData, ptrdiff_t length, bool takeOwnership) {
    assert(length == getContiguousDataLength());
    if (rep->m_owner) {
        MatrixHelperRep<S>::deleteAllocatedMemory(rep->m_data);
        rep->m_data = 0;
    }
    rep->m_data = newData;
    rep->m_owner = takeOwnership;
}
template <class S>
void MatrixHelper<S>::replaceContiguousData(const S* newData, ptrdiff_t length) {
    replaceContiguousData(const_cast<S*>(newData), length, false);
    rep->m_writable = false;
}
template <class S>
void MatrixHelper<S>::swapOwnedContiguousData(S* newData, ptrdiff_t length, S*& oldData) {
    assert(length == getContiguousDataLength());
    assert(rep->m_owner);
    oldData = rep->m_data;
    rep->m_data = newData;
}


//----------------------------- MATRIX HELPER REP ------------------------------
//
//------------------------------------------------------------------------------

template <class S>
MatrixHelperRep<S>*
MatrixHelperRep<S>::createOwnerMatrixHelperRep(int esz, int cppEsz, const MatrixCharacter& want) {
    SimTK_ASSERT2((esz == 1 && cppEsz == 1) || (esz > 1 && cppEsz >= esz),
                  "MatrixHelperRep::createOwnerMatrixHelperRep(): bad element size esz=%d, cppEsz=%d",
                  esz,
                  cppEsz);

    MatrixHelperRep<S>* rep = 0;

    const int nr = want.nrow();
    const int nc = want.ncol();
    const MatrixStructure& structure = want.getStructure();
    const MatrixStorage& storage = want.getStorage();
    const bool rowOrder = (storage.getOrder() == MatrixStorage::RowOrder);

    switch (structure.getStructure()) {
        case MatrixStructure::Full:
            if (rowOrder) {
                rep = (esz == 1 ? (RegularFullHelper<S>*)new FullRowOrderScalarHelper<S>(nr, nc)
                                : (RegularFullHelper<S>*)new FullRowOrderEltHelper<S>(esz, cppEsz, nr, nc));
            } else {
                rep = (esz == 1 ? (RegularFullHelper<S>*)new FullColOrderScalarHelper<S>(nr, nc)
                                : (RegularFullHelper<S>*)new FullColOrderEltHelper<S>(esz, cppEsz, nr, nc));
            }
            break;

        case MatrixStructure::Triangular:
        case MatrixStructure::Symmetric:
        case MatrixStructure::Hermitian:
        case MatrixStructure::SkewSymmetric:
        case MatrixStructure::SkewHermitian: {
            const bool triangular = structure.getStructure() == MatrixStructure::Triangular;
            const bool hermitian = structure.getStructure() == MatrixStructure::Hermitian
                                   || structure.getStructure() == MatrixStructure::SkewHermitian;
            const bool skew = structure.getStructure() == MatrixStructure::SkewSymmetric
                              || structure.getStructure() == MatrixStructure::SkewHermitian;

            if (/*storage.getPlacement() == MatrixStorage::Upper*/ true) {
                rep = (esz == 1 ? (TriInFullHelper<S>*)new TriInFullUpperHelper<
                                      S>(1, 1, nr, nc, triangular, hermitian, skew, rowOrder)
                                : (TriInFullHelper<S>*)new TriInFullUpperHelper<
                                      S>(esz, cppEsz, nr, nc, triangular, hermitian, skew, rowOrder));
            }
            // else
            //   rep = (esz == 1 ? (TriInFullHelper<S>*)new TriInFullLowerHelper<S>(1,1,nr,nc,
            //                                                false,true,false,rowOrder)
            //                  : (TriInFullHelper<S>*)new TriInFullLowerHelper<S>(esz,cppEsz,nr,nc,
            //                                                false,true,false,rowOrder));
            break;
        }

        case MatrixStructure::Matrix1d: {
            assert(nr == 1 || nc == 1);
            const int length = nr * nc;
            rep = (esz == 1
                       ? (FullVectorHelper<S>*)new ContiguousVectorScalarHelper<S>(length, rowOrder)
                       : (FullVectorHelper<S>*)new ContiguousVectorHelper<S>(esz, cppEsz, length, rowOrder));
            break;
        }

        default:
            SimTK_ERRCHK1(!"not implemented",
                          "MatrixHelperRep::createOwnerMatrixHelperRep()",
                          "Matrix structure commitment %s not implemented yet.",
                          MatrixStructure::name(structure.getStructure()));
    }

    return rep;
}


template <class S>
MatrixHelperRep<S>* MatrixHelperRep<S>::createExternalMatrixHelperRep(int esz,
                                                                      int cppEsz,
                                                                      const MatrixCharacter& actual,
                                                                      int spacing,
                                                                      S* data,
                                                                      bool canWrite) {
    SimTK_ASSERT2((esz == 1 && cppEsz == 1) || (esz > 1 && cppEsz >= esz),
                  "MatrixHelperRep::createExternalMatrixHelperRep(): bad element size esz=%d, cppEsz=%d",
                  esz,
                  cppEsz);

    MatrixHelperRep<S>* rep = 0;

    const int nr = actual.nrow();
    const int nc = actual.ncol();
    const MatrixStructure& structure = actual.getStructure();
    const MatrixStorage& storage = actual.getStorage();
    const bool rowOrder = (storage.getOrder() == MatrixStorage::RowOrder);

    switch (structure.getStructure()) {
        case MatrixStructure::Full:
            if (rowOrder) {
                rep = (esz == 1 ? (RegularFullHelper<S>*)new FullRowOrderScalarHelper<S>(nr,
                                                                                         nc,
                                                                                         spacing,
                                                                                         data,
                                                                                         canWrite)
                                : (RegularFullHelper<S>*)new FullRowOrderEltHelper<S>(esz,
                                                                                      cppEsz,
                                                                                      nr,
                                                                                      nc,
                                                                                      spacing,
                                                                                      data,
                                                                                      canWrite));
            } else {
                rep = (esz == 1 ? (RegularFullHelper<S>*)new FullColOrderScalarHelper<S>(nr,
                                                                                         nc,
                                                                                         spacing,
                                                                                         data,
                                                                                         canWrite)
                                : (RegularFullHelper<S>*)new FullColOrderEltHelper<S>(esz,
                                                                                      cppEsz,
                                                                                      nr,
                                                                                      nc,
                                                                                      spacing,
                                                                                      data,
                                                                                      canWrite));
            }
            break;

        case MatrixStructure::Triangular:
        case MatrixStructure::Symmetric:
        case MatrixStructure::Hermitian:
        case MatrixStructure::SkewSymmetric:
        case MatrixStructure::SkewHermitian: {
            const bool triangular = structure.getStructure() == MatrixStructure::Triangular;
            const bool hermitian = structure.getStructure() == MatrixStructure::Hermitian
                                   || structure.getStructure() == MatrixStructure::SkewHermitian;
            const bool skew = structure.getStructure() == MatrixStructure::SkewSymmetric
                              || structure.getStructure() == MatrixStructure::SkewHermitian;

            if (/*storage.getPlacement() == MatrixStorage::Upper*/ true) {
                rep = (esz == 1 ? (TriInFullHelper<S>*)new TriInFullUpperHelper<S>(1,
                                                                                   1,
                                                                                   nr,
                                                                                   nc,
                                                                                   triangular,
                                                                                   hermitian,
                                                                                   skew,
                                                                                   rowOrder,
                                                                                   spacing,
                                                                                   data,
                                                                                   canWrite)
                                : (TriInFullHelper<S>*)new TriInFullUpperHelper<S>(esz,
                                                                                   cppEsz,
                                                                                   nr,
                                                                                   nc,
                                                                                   triangular,
                                                                                   hermitian,
                                                                                   skew,
                                                                                   rowOrder,
                                                                                   spacing,
                                                                                   data,
                                                                                   canWrite));
            }
            // else
            //   rep = (esz == 1 ? (TriInFullHelper<S>*)new TriInFullLowerHelper<S>(1,1,nr,nc,
            //                                                false,true,false,rowOrder)
            //                  : (TriInFullHelper<S>*)new TriInFullLowerHelper<S>(esz,cppEsz,nr,nc,
            //                                                false,true,false,rowOrder));
            break;
        }

        case MatrixStructure::Matrix1d: {
            assert(nr == 1 || nc == 1);
            const int length = nr * nc;
            const int strideInElements = spacing / esz;
            if (strideInElements > 1) {
                rep = (esz == 1 ? (FullVectorHelper<S>*)new StridedVectorScalarHelper<S>(length,
                                                                                         rowOrder,
                                                                                         strideInElements,
                                                                                         data,
                                                                                         canWrite)
                                : (FullVectorHelper<S>*)new StridedVectorHelper<S>(esz,
                                                                                   cppEsz,
                                                                                   length,
                                                                                   rowOrder,
                                                                                   strideInElements,
                                                                                   data,
                                                                                   canWrite));
            } else {
                rep = (esz == 1 ? (FullVectorHelper<S>*)new ContiguousVectorScalarHelper<S>(length,
                                                                                            rowOrder,
                                                                                            data,
                                                                                            canWrite)
                                : (FullVectorHelper<S>*)new ContiguousVectorHelper<S>(esz,
                                                                                      cppEsz,
                                                                                      length,
                                                                                      rowOrder,
                                                                                      data,
                                                                                      canWrite));
            }
            break;
        }

        default:
            SimTK_ERRCHK1(!"not implemented",
                          "MatrixHelperRep::createOwnerMatrixHelperRep()",
                          "Matrix structure commitment %s not implemented yet.",
                          MatrixStructure::name(structure.getStructure()));
    }

    return rep;
}

template <class S>
void MatrixHelperRep<S>::scaleBy(const typename CNT<S>::StdNumber& s) {
    // XXX -- really, really bad! Optimize for contiguous data!
    for (int j = 0; j < ncol(); ++j) {
        for (int i = 0; i < nrow(); ++i) {
            scaleElt(updElt(i, j), s);
        }
    }
}

template <class S>
void MatrixHelperRep<S>::addIn(const MatrixHelper<S>& h) {
    const MatrixHelperRep& hrep = h.getRep();

    assert(nrow() == hrep.nrow() && ncol() == hrep.ncol());
    assert(getEltSize() == hrep.getEltSize());
    // XXX -- really, really bad! Optimize for contiguous data, missing views, etc.!
    for (int j = 0; j < ncol(); ++j) {
        for (int i = 0; i < nrow(); ++i) {
            addToElt(updElt(i, j), hrep.getElt(i, j));
        }
    }
}
template <class S>
void MatrixHelperRep<S>::addIn(const MatrixHelper<typename CNT<S>::TNeg>& nh) {
    subIn(reinterpret_cast<const MatrixHelper<S>&>(nh));
}

template <class S>
void MatrixHelperRep<S>::subIn(const MatrixHelper<S>& h) {
    const MatrixHelperRep& hrep = h.getRep();

    assert(nrow() == hrep.nrow() && ncol() == hrep.ncol());
    assert(getEltSize() == hrep.getEltSize());
    // XXX -- really, really bad! Optimize for contiguous data, missing views, etc.!
    for (int j = 0; j < ncol(); ++j) {
        for (int i = 0; i < nrow(); ++i) {
            subFromElt(updElt(i, j), hrep.getElt(i, j));
        }
    }
}
template <class S>
void MatrixHelperRep<S>::subIn(const MatrixHelper<typename CNT<S>::TNeg>& nh) {
    addIn(reinterpret_cast<const MatrixHelper<S>&>(nh));
}

template <class S>
void MatrixHelperRep<S>::fillWith(const S* eltp) {
    if (hasContiguousData()) {
        const ptrdiff_t len = nelt();
        if (getEltSize() == 1) {
            for (ptrdiff_t i = 0; i < len; i++) {
                m_data[i] = *eltp;
            }
        } else {
            for (ptrdiff_t i = 0; i < len; i++) {
                for (int j = 0; j < getEltSize(); j++) {
                    m_data[i * getEltSize() + j] = eltp[j];
                }
            }
        }
    } else {
        for (int j = 0; j < ncol(); ++j) {
            for (int i = 0; i < nrow(); ++i) {
                copyElt(updElt(i, j), eltp);
            }
        }
    }
}

// We're copying data from a C++ row-oriented matrix into our general
// Matrix. In addition to the row ordering, C++ may use different spacing
// for elements than Simmatrix does. Lucky we know that value!
template <class S>
void MatrixHelperRep<S>::copyInByRowsFromCpp(const S* elts) {
    const int cppRowSz = m_cppEltSize * ncol();
    // XXX -- really, really bad! Optimize for contiguous data, missing views, etc.!
    for (int j = 0; j < ncol(); ++j) {
        for (int i = 0; i < nrow(); ++i) {
            copyElt(updElt(i, j), elts + i * cppRowSz + j * m_cppEltSize);
        }
    }
}

template <class S>
MatrixHelperRep<S>::~MatrixHelperRep() {
    if (isOwner()) {
        deleteAllocatedMemory(m_data);
    }
}

template <class S>
static void dumpElt(const S* p, int sz) {
    if (sz > 1) {
        std::cout << "{";
    }
    for (int k = 0; k < sz; ++k) {
        if (k > 0) {
            std::cout << " ";
        }
        std::cout << *p++;
    }
    if (sz > 1) {
        std::cout << "}";
    }
}

template <class S>
void MatrixHelperRep<S>::dump(const char* msg) const {
    if (msg) {
        std::cout << std::string(msg) << std::endl;
    }
    std::cout << "Matrix " << nrow() << " X " << ncol() << " " << getEltSize()
              << "-scalar entries:" << std::endl;
    if (nrow() * ncol() == 0) {
        std::cout << "<EMPTY>" << std::endl;
        return;
    }

    S* elt = new S[getEltSize()];
    const std::streamsize oldsz = std::cout.precision(20);
    for (int i = 0; i < nrow(); ++i) {
        for (int j = 0; j < ncol(); ++j) {
            if (j > 0) {
                std::cout << "\t";
            }
            getAnyElt(i, j, elt);
            dumpElt(elt, getEltSize());
        }
        std::cout << "\n";
    }
    std::cout.precision(oldsz);
    delete[] elt;
}

//----------------------------- RegularFullHelper ------------------------------
//------------------------------------------------------------------------------

template <class S>
VectorHelper<S>* RegularFullHelper<S>::createDiagonalView_() {
    VectorHelper<S>* p = 0;
    const int length = std::min(this->nrow(), this->ncol());
    S* data = length ? this->updElt_(0, 0) : 0;

    const int strideInScalars = length > 1 ? int(this->getElt_(1, 1) - this->getElt_(0, 0)) : this->m_eltSize;
    const int strideInElements = strideInScalars / this->m_eltSize;

    // No need for a stride if there's 0 or 1 element, or if the stride is 1. TODO: scalar helper
    if (strideInElements == 1) {
        p = (this->m_eltSize == 1)
                ? (VectorHelper<S>*)new ContiguousVectorScalarHelper<S>(length, false, data, false)
                : (VectorHelper<S>*)new ContiguousVectorHelper<S>(this->m_eltSize,
                                                                  this->m_cppEltSize,
                                                                  length,
                                                                  false,
                                                                  data,
                                                                  false);
        return p;
    }

    p = (this->m_eltSize == 1)
            ? (VectorHelper<S>*)new StridedVectorScalarHelper<S>(length, false, strideInElements, data, false)
            : (VectorHelper<S>*)new StridedVectorHelper<S>(this->m_eltSize,
                                                           this->m_cppEltSize,
                                                           length,
                                                           false,
                                                           strideInElements,
                                                           data,
                                                           false);
    return p;
}

template <class S>
VectorHelper<S>* RegularFullHelper<S>::createColumnView_(int j, int i, int m) {
    VectorHelper<S>* p = 0;
    S* data = m ? this->updElt_(i, j) : 0;

    const int strideInScalars = m > 1 ? int(this->getElt_(i + 1, j) - this->getElt_(i, j)) : this->m_eltSize;
    const int strideInElements = strideInScalars / this->m_eltSize;

    // No need for a stride if there's 0 or 1 element, or if the stride is 1. TODO: scalar helper
    if (strideInElements == 1) {
        p = (this->m_eltSize == 1)
                ? (VectorHelper<S>*)new ContiguousVectorScalarHelper<S>(m, false, data, false)
                : (VectorHelper<S>*)new ContiguousVectorHelper<S>(this->m_eltSize,
                                                                  this->m_cppEltSize,
                                                                  m,
                                                                  false,
                                                                  data,
                                                                  false);
        return p;
    }

    p = (this->m_eltSize == 1)
            ? (VectorHelper<S>*)new StridedVectorScalarHelper<S>(m, false, strideInElements, data, false)
            : (VectorHelper<S>*)new StridedVectorHelper<S>(this->m_eltSize,
                                                           this->m_cppEltSize,
                                                           m,
                                                           false,
                                                           strideInElements,
                                                           data,
                                                           false);
    return p;
}

template <class S>
VectorHelper<S>* RegularFullHelper<S>::createRowView_(int i, int j, int n) {
    VectorHelper<S>* p = 0;
    S* data = n ? this->updElt_(i, j) : 0;

    const int strideInScalars = n > 1 ? int(this->getElt_(i, j + 1) - this->getElt_(i, j)) : this->m_eltSize;
    const int strideInElements = strideInScalars / this->m_eltSize;

    // No need for a stride if there's 0 or 1 element, or if the stride is 1. TODO: scalar helper
    if (strideInElements == 1) {
        p = (this->m_eltSize == 1)
                ? (VectorHelper<S>*)new ContiguousVectorScalarHelper<S>(n, true, data, false)
                : (VectorHelper<S>*)new ContiguousVectorHelper<S>(this->m_eltSize,
                                                                  this->m_cppEltSize,
                                                                  n,
                                                                  true,
                                                                  data,
                                                                  false);
        return p;
    }

    p = (this->m_eltSize == 1)
            ? (VectorHelper<S>*)new StridedVectorScalarHelper<S>(n, true, strideInElements, data, false)
            : (VectorHelper<S>*)new StridedVectorHelper<S>(this->m_eltSize,
                                                           this->m_cppEltSize,
                                                           n,
                                                           true,
                                                           strideInElements,
                                                           data,
                                                           false);
    return p;
}


