    // no default constructor
    explicit DecorativeConeRep
        (const Vec3& orig, const Vec3& dir, Real& h, Real& baseR) 
    :   origin(orig), direction(dir), height(h), baseRadius(baseR) {
    }

    const Vec3& getOrigin() const {
        return  origin;
    }

    const UnitVec3& getDirection() const {
        return  direction;
    }

    const Real& getHeight() const {
        return  height;
    }

    const Real& getBaseRadius() const {
        return baseRadius;
    }
    void setOrigin(const Vec3& orig) {
        origin = orig;
    }
    void setDirection(const UnitVec3& dir) {
        direction = dir;
    }
    void setHeight(Real& h) {
        height = h;
    }
    void setBaseRadius(Real& baseR) {
        baseRadius = baseR;
    }
    // virtuals
    DecorativeGeometryRep* cloneDecorativeGeometryRep() const override {
        DecorativeConeRep* DGRep = new DecorativeConeRep(*this);
        return DGRep;
    }

    void implementGeometry(DecorativeGeometryImplementation& geometry) const override {
        geometry.implementConeGeometry(getMyConeHandle());
    }

    SimTK_DOWNCAST(DecorativeConeRep, DecorativeGeometryRep);
private:
    Vec3 origin;
    UnitVec3 direction;
    Real height;
    Real baseRadius;

    // This is just a static downcast since the DecorativeGeometry handle class 
    // is not virtual.

    const DecorativeCone& getMyConeHandle() const {
        return *static_cast<const DecorativeCone*>(myHandle);
    }
};

    ////////////////////
    // DecorationsRep //
    ////////////////////

class DecorationsRep : public DecorativeGeometryRep {
public:
    DecorationsRep() {}

    int addDecoration(const DecorativeGeometry& decoration) {
        geom.push_back(decoration);
        return (int)(geom.size()-1);
    }
    int addDecoration(const Transform& X_DE,
                      const DecorativeGeometry& element) {
        geom.push_back(element);
        // The current transform goes from the element's frame E to the 
        // frame G of the actual geometry. We would normally put E at the
        // Decorations frame D, but now we want to relocate it.
        const Transform& X_EG = geom.back().getTransform();
        geom.back().setTransform(X_DE*X_EG);
        return (int)(geom.size()-1);
    }

    int getNumDecorations() const {return (int)geom.size();}
    const DecorativeGeometry& getDecoration(int i) const {return geom[i];}

    // virtuals

    DecorationsRep* cloneDecorativeGeometryRep() const override {
        DecorationsRep* DGRep = new DecorationsRep(*this);
        return DGRep; 
    }

    void implementGeometry(DecorativeGeometryImplementation& geometry) const override {
        for (unsigned i=0; i < geom.size(); ++i) {
            DecorativeGeometry copy = geom[i];
            copy.updRep().inheritPropertiesFrom(*this);
            copy.implementGeometry(geometry);
        }
    }

    SimTK_DOWNCAST(DecorationsRep, DecorativeGeometryRep);
private:
    Array_<DecorativeGeometry> geom;

    // This is just a static downcast since the DecorativeGeometry handle class
    // is not virtual.
    const Decorations& getMyHandle() const {
        return *static_cast<const Decorations*>(myHandle);
    }
};


