------------------------------------------------------------------- * Change Record : * * Version Author/Date Description of changes * ------- ----------- ---------------------- * 01.01 HVE/021101 Initial release * 01.02 PE/8Aug07 Converted to a class, templatized * * End of Change Record * -------------------------------------------------------------------------- */
#include <float.h>
namespace SimTK {
template<class T> class CPoly { public: static char _V_[]; int findRoots( const T *opr, const T *opi, int degree, T *zeror, T *zeroi ); private: T sr, si, tr, ti, pvr, pvi, are, mre, eta, infin; int nn; T *pr, *pi, *hr, *hi, *qpr, *qpi, *qhr, *qhi, *shr, *shi; void noshft( const int l1 ); void fxshft( const int l2, T *zr, T *zi, int *conv ); void vrshft( const int l3, T *zr, T *zi, int *conv ); void calct( int *bol ); void nexth( const int bol ); void polyev( const int nn, const T sr, const T si, const T pr[], const T pi[], T qr[], T qi[], T *pvr, T *pvi ); T errev( const int nn, const T qr[], const T qi[], const T ms, const T mp, const T are, const T mre ); void cauchy( const int nn, T pt[], T q[], T *fn_val ); T scale( const int nn, const T pt[], const T eta, const T infin, const T smalno, const T base ); void cdivid( const T ar, const T ai, const T br, const T bi, T *cr, T *ci ); T cmod( const T r, const T i ); void mcon( T *eta, T *infiny, T *smalno, T *base ); };
