/*! <!-- Stage info --> */
const void System::Guts::PrintDefaultStateStages() const {
    if (!systemTopologyHasBeenRealized()) {
        std::cout << " System topology has NOT been realized yet." << std::endl << std::flush;
        return;
    }

    State& defaultState = getRep().defaultState; // mutable
    const Stage& defStage = defaultState.getSystemStage();
    std::cout << "StageInfo::defState " << defStage << std::endl;

    for (SubsystemIndex i(0); i < defaultState.getNumSubsystems(); ++i) {
        std::cout << " (" << i;
        std::cout << " " << defaultState.getSubsystemName(i);
        std::cout << " " << defaultState.getSubsystemVersion(i);
        std::cout << " " << defaultState.getSubsystemStage(i);
        std::cout << ")";
    }
    std::cout << "\n";
}


/*! <!-- Stage info --> */
const void System::Guts::PrintSubsystemsStages() const {
    if (!systemTopologyHasBeenRealized()) {
        std::cout << " System topology has NOT been realized yet." << std::endl << std::flush;
        return;
    }

    std::cout << "StageInfo::SystemTopologyVersion" << getRep().getSystemTopologyCacheVersion() << std::endl;

    std::cout << "StageInfo::Subsystems stages" << std::endl;
    for (SubsystemIndex i(0); i < getNumSubsystems(); ++i) {
        std::cout << " (" << i;
        std::cout << " " << getRep().subsystems[i].getName();
        std::cout << " " << getRep().subsystems[i].getVersion() << " "
                  << getRep().getSystemTopologyCacheVersion();
        std::cout << " " << getRep().subsystems[i].getStage(getRep().defaultState);
        std::cout << ")";
    }
    std::cout << "\n";

    std::cout << "StageInfo::System realizations of each Stage To M I Ti P V D A R";
    std::cout << " " << getRep().nRealizationsOfStage[Stage::Topology];
    std::cout << " " << getRep().nRealizationsOfStage[Stage::Model];
    std::cout << " " << getRep().nRealizationsOfStage[Stage::Instance];
    std::cout << " " << getRep().nRealizationsOfStage[Stage::Time];
    std::cout << " " << getRep().nRealizationsOfStage[Stage::Position];
    std::cout << " " << getRep().nRealizationsOfStage[Stage::Velocity];
    std::cout << " " << getRep().nRealizationsOfStage[Stage::Dynamics];
    std::cout << " " << getRep().nRealizationsOfStage[Stage::Acceleration];
    std::cout << " " << getRep().nRealizationsOfStage[Stage::Report];
    std::cout << "\n";
}


//------------------------------------------------------------------------------
//                            REALIZE TOPOLOGY
//------------------------------------------------------------------------------
const State& System::Guts::realizeTopology() const {
    State& defaultState = getRep().defaultState; // mutable
    if (getRep().systemTopologyHasBeenRealized()) {
        return defaultState;
    }

    defaultState.clear();
    defaultState.setNumSubsystems(getNumSubsystems());
    for (SubsystemIndex i(0); i < getNumSubsystems(); ++i) {
        defaultState.initializeSubsystem(i,
                                         getRep().subsystems[i].getName(),
                                         getRep().subsystems[i].getVersion());
    }

    // Allow the concrete System subclass to do its processing.
    realizeTopologyImpl(defaultState); // defaultState is mutable

    // Realize any subsystems that the subclass didn't already take care of.
    for (SubsystemIndex i(0); i < getNumSubsystems(); ++i) {
        if (getRep().subsystems[i].getStage(defaultState) < Stage::Topology) {
            getRep().subsystems[i].getSubsystemGuts().realizeSubsystemTopology(defaultState);
        }
    }

    // Force the defaultState's Topology stage version number to match the
    // Topology cache version in this System.
    defaultState.setSystemTopologyStageVersion(getRep().getSystemTopologyCacheVersion());
    defaultState.advanceSystemToStage(Stage::Topology);

    getRep().systemTopologyRealized = true;           // mutable
    getRep().nRealizationsOfStage[Stage::Topology]++; // mutable counter

    // Realize the model using the default settings of the Model variables.
    // This allocates all the later-stage State variables.
    realizeModel(defaultState);

    return defaultState;
}


//------------------------------------------------------------------------------
//                              REALIZE MODEL
//------------------------------------------------------------------------------
void System::Guts::realizeModel(State& s) const {
    SimTK_STAGECHECK_TOPOLOGY_REALIZED_ALWAYS(systemTopologyHasBeenRealized(),
                                              "System",
                                              getName(),
                                              "System::Guts::realizeModel()");
    SimTK_STAGECHECK_GE_ALWAYS(s.getSystemStage(), Stage::Topology, "System::Guts::realizeModel()");
    SimTK_STAGECHECK_TOPOLOGY_VERSION_ALWAYS(getSystemTopologyCacheVersion(),
                                             s.getSystemTopologyStageVersion(),
                                             "System",
                                             getName(),
                                             "System::Guts::realizeModel()");
    if (s.getSystemStage() < Stage::Model) {
        // Allow the subclass to do its processing.
        realizeModelImpl(s);
        // Realize any subsystems that the subclass didn't already take care of.
        for (SubsystemIndex i(0); i < getNumSubsystems(); ++i) {
            if (getRep().subsystems[i].getStage(s) < Stage::Model) {
                getRep().subsystems[i].getSubsystemGuts().realizeSubsystemModel(s);
            }
        }
        s.advanceSystemToStage(Stage::Model);

        getRep().nRealizationsOfStage[Stage::Model]++; // mutable counter
    }
}


//------------------------------------------------------------------------------
//                             REALIZE INSTANCE
//------------------------------------------------------------------------------
void System::Guts::realizeInstance(const State& s) const {
    SimTK_STAGECHECK_GE_ALWAYS(s.getSystemStage(),
                               Stage(Stage::Instance).prev(),
                               "System::Guts::realizeInstance()");
    if (s.getSystemStage() < Stage::Instance) {
        realizeInstanceImpl(s); // take care of the Subsystems
        // Realize any subsystems that the subclass didn't already take care of.
        for (SubsystemIndex i(0); i < getNumSubsystems(); ++i) {
            if (getRep().subsystems[i].getStage(s) < Stage::Instance) {
                getRep().subsystems[i].getSubsystemGuts().realizeSubsystemInstance(s);
            }
        }
        s.advanceSystemToStage(Stage::Instance);

        getRep().nRealizationsOfStage[Stage::Instance]++; // mutable counter
    }
}


