//------------------------------------------------------------------------------
//                                 REALIZE
//------------------------------------------------------------------------------
void System::Guts::realize(const State& s, Stage g) const {
    SimTK_STAGECHECK_GE_ALWAYS(s.getSystemStage(), Stage::Model, "System::Guts::realize()");

    Stage stageNow = Stage::Empty;
    while ((stageNow = s.getSystemStage()) < g) {
        switch (stageNow) {
            case Stage::Model:
                realizeInstance(s);
                break;
            case Stage::Instance:
                realizeTime(s);
                break;
            case Stage::Time:
                realizePosition(s);
                break;
            case Stage::Position:
                realizeVelocity(s);
                break;
            case Stage::Velocity:
                realizeDynamics(s);
                break;
            case Stage::Dynamics:
                realizeAcceleration(s);
                break;
            case Stage::Acceleration:
                realizeReport(s);
                break;
            default:
                assert(!"System::Guts::realize(): bad stage");
        }
    }
}

//------------------------------------------------------------------------------
//                   CALC DECORATIVE GEOMETRY AND APPEND
//------------------------------------------------------------------------------
void System::Guts::calcDecorativeGeometryAndAppend(const State& s,
                                                   Stage stage,
                                                   Array_<DecorativeGeometry>& geom) const {
    assert(stage == Stage::Topology || s.getSystemStage() >= stage);
    for (SubsystemIndex i(0); i < getNumSubsystems(); ++i) {
        getRep().subsystems[i].getSubsystemGuts().calcDecorativeGeometryAndAppend(s, stage, geom);
    }
}


