/**@file * This file is the user-includeable header to be included in * user programs to provide fixed-length Vec & Mat classes. The * included internal headers declare templates needed for zero-overhead handling of small * vectors and matrices. The idea is to convey all needed information, * including the size, at compile time through the templatized types. * These classes have well-defined minimal storage layouts and can * be easily interconverted to/from arrays of scalar types, with zero * conversion overhead. * * There are three generic types required: a column vector Vec, a row * vector (a.k.a. "covector") Row, and a matrix Mat. Real and Complex * elements at single, double, and quad precision are supported. * Almost all operations are inline -- this package is intended to * provide performance as good as one could achieve by special-purpose C code. * * When the element type is a "basic numerical type" then the resulting * Vec, Row or Mat is also a basic numerical type, so these can * be built up with structured elements so that Vec< 2,Vec<3> > for * example is a 2-element vector whose elements are Vec<3>'s. * * These classes are designed so that many operations that look like * computations are free. These include: negation, conjugation, extraction * of real and imaginary parts from complex numerical types, and * hermitian or positional transpose. These are performed * by type casting rather than computation. That is, these operations * can be viewed as a change in perspective rather than an actual * computation. * * To achieve zero overhead, separate types are needed to convey * special matrix structure, although appropriate interconversions * are defined. So symmetric matrices are SymMat's and diagonal * matrices are DiagMat's. Note that symmetric matrices are more * properly called Hermitian in that the reflected elements are * conjugates of one another. * * Supported operations * * Class member functions for Vec<M>: * Unary: -, +, ~ (Hermitian transpose) * Assignment: copy assignment of identical object * elementwise assignment from any M-row Vec or Mat * scalar assignment to each element * TODO * * Global operations involving only Vecs or Vec and scalar, * yielding a vector result. (Row has the same set.) * v+s, s+v, v+v * v-s, s-v, v-v * v*s, s*v (can't multiply a vector by another vector) * v/s * v==s, s==v, v==v (same for !=) * * Global operations mixing Row, Vec, Mat * s=r*v (dot product) * m=v*r (outer product) * v=m*v, r=r*m * m=m*m (with compatible dimensions) * */
#include "SimTKcommon/Scalar.h" #include "SimTKcommon/TemplatizedLapack.h"
#include "SimTKcommon/internal/ResultType.h" #include "SimTKcommon/internal/Vec.h" #include "SimTKcommon/internal/Row.h" #include "SimTKcommon/internal/Mat.h" #include "SimTKcommon/internal/SymMat.h" #include "SimTKcommon/internal/SmallMatrixMixed.h"
// Friendly abbreviations. namespace SimTK { /** @defgroup MatVecTypedefs Predefined typedefs @ingroup MatVecUtilities
These typedefs provide convenient synonyms for common matrix and vector types. Note that the typedef name may be used interchangeably with the fully templatized names; they represent exactly the same type.
The simplest names are for types whose elements are of the compile-time default precision type @ref SimTK::Real "Real" which is typically \c double but can be changed to \c float at compile time. There are also names prefixed with a lowercase "f" that always use float regardless of the default precision.
Note that there are more template parameters than are specified here; these typedefs are using default values for them. The missing parameters specify the spacing between elements; these typedefs always refer to types for which the elements are packed in memory. See Vec, Row, Mat, SymMat for more information.
For fixed size vectors and matrices, only the 2-, 3-, and 4-element sizes are commonly used. However we provide typedefs for sizes up to 9 in case they are needed. For larger sizes, just use the explicit templatized forms. **/ /**@{**/ /** This is the most common 2D vector type: a column of 2 Real values stored consecutively in memory (packed). **/ typedef Vec<2> Vec2; /** This is the most common 3D vector type: a column of 3 Real values stored consecutively in memory (packed). **/ typedef Vec<3> Vec3; /** This is the most common 4D vector type: a column of 4 Real values stored consecutively in memory (packed). **/ typedef Vec<4> Vec4;
/** This is the most common 2x2 matrix type: two packed columns of 2 Real values each. The columns have type \c Vec2 but rows have a stride of 2 so the row type is \c Row<2,Real,2>, \e not \c Row2. **/ typedef Mat<2, 2> Mat22; /** This is the most common 3x3 matrix type: three packed columns of 3 Real values each. The columns have type \c Vec3 but rows have a stride of 3 so the row type is \c Row<3,Real,3>, \e not \c Row3. **/ typedef Mat<3, 3> Mat33; /** This is the most common 4x4 matrix type: four packed columns of 4 Real values each. The columns have type \c Vec4 but rows have a stride of 4 so the row type is \c Row<4,Real,4>, \e not \c Row4. **/ typedef Mat<4, 4> Mat44;
/** A compact, 2x2 Real symmetric matrix; only 3 elements are stored. **/ typedef SymMat<2> SymMat22; /** A compact, 3x3 Real symmetric matrix; only 6 elements are stored. **/ typedef SymMat<3> SymMat33; /** A compact, 2x2 Real symmetric matrix; only 10 elements are stored. **/ typedef SymMat<4> SymMat44;
/** Packed, 2-element row of Real values. This is the type of a transposed Vec2 and usually does not appear explicitly in user programs. **/ typedef Row<2> Row2; /** Packed, 3-element row of Real values. This is the type of a transposed Vec3 and usually does not appear explicitly in user programs. **/ typedef Row<3> Row3; /** Packed, 4-element row of Real values. This is the type of a transposed Vec4 and usually does not appear explicitly in user programs. **/ typedef Row<4> Row4; /**@}**/
/** @defgroup UncommonMatVecTypedefs Less commonly-used typedefs @ingroup MatVecTypedefs **/ /**@{**/
// Less-popular Vec typedefs. typedef Vec<1> Vec1; ///< A vector of just one Real element (not too useful). typedef Vec<5> Vec5; ///< Packed, 5-element vector of Real values. typedef Vec<6> Vec6; ///< Packed, 6-element vector of Real values. typedef Vec<7> Vec7; ///< Packed, 7-element vector of Real values. typedef Vec<8> Vec8; ///< Packed, 8-element vector of Real values. typedef Vec<9> Vec9; ///< Packed, 9-element vector of Real values.
