typedef Mat<5,1> Mat51; ///< 5x1 Real column matrix. typedef Mat<5,2> Mat52; ///< 5x2 Real matrix, packed by columns. typedef Mat<5,3> Mat53; ///< 5x3 Real matrix, packed by columns. typedef Mat<5,4> Mat54; ///< 5x4 Real matrix, packed by columns. typedef Mat<5,5> Mat55; ///< 5x5 Real matrix, packed by columns. typedef Mat<5,6> Mat56; ///< 5x6 Real matrix, packed by columns. typedef Mat<5,7> Mat57; ///< 5x7 Real matrix, packed by columns. typedef Mat<5,8> Mat58; ///< 5x8 Real matrix, packed by columns. typedef Mat<5,9> Mat59; ///< 5x9 Real matrix, packed by columns.
typedef Mat<6,1> Mat61; ///< 6x1 Real column matrix. typedef Mat<6,2> Mat62; ///< 6x2 Real matrix, packed by columns. typedef Mat<6,3> Mat63; ///< 6x3 Real matrix, packed by columns. typedef Mat<6,4> Mat64; ///< 6x4 Real matrix, packed by columns. typedef Mat<6,5> Mat65; ///< 6x5 Real matrix, packed by columns. typedef Mat<6,6> Mat66; ///< 6x6 Real matrix, packed by columns. typedef Mat<6,7> Mat67; ///< 6x7 Real matrix, packed by columns. typedef Mat<6,8> Mat68; ///< 6x8 Real matrix, packed by columns. typedef Mat<6,9> Mat69; ///< 6x9 Real matrix, packed by columns.
