typedef Mat<8,1> Mat81; ///< 8x1 Real column matrix. typedef Mat<8,2> Mat82; ///< 8x2 Real matrix, packed by columns. typedef Mat<8,3> Mat83; ///< 8x3 Real matrix, packed by columns. typedef Mat<8,4> Mat84; ///< 8x4 Real matrix, packed by columns. typedef Mat<8,5> Mat85; ///< 8x5 Real matrix, packed by columns. typedef Mat<8,6> Mat86; ///< 8x6 Real matrix, packed by columns. typedef Mat<8,7> Mat87; ///< 8x7 Real matrix, packed by columns. typedef Mat<8,8> Mat88; ///< 8x8 Real matrix, packed by columns. typedef Mat<8,9> Mat89; ///< 8x9 Real matrix, packed by columns.
