// Microsoft compiler security
static FILE* TiXmlFOpen( const char* filename, const char* mode )
{
    #if defined(_MSC_VER) && (_MSC_VER >= 1400 )
        FILE* fp = 0;
        errno_t err = fopen_s( &fp, filename, mode );
        if ( !err && fp )
            return fp;
        return 0;
    #else
        return fopen( filename, mode );
    #endif
}

