void TiXmlElement::SetAttribute( const char * name, int val )
{    
    char buf[64];
    #if defined(TIXML_SNPRINTF)        
        TIXML_SNPRINTF( buf, sizeof(buf), "%d", val );
    #else
        sprintf( buf, "%d", val );
    #endif
    SetAttribute( name, buf );
}


void TiXmlElement::SetAttribute( const String& name, int val )
{    
   std::ostringstream oss;
   oss << val;
   SetAttribute( name, oss.str() );
}


void TiXmlElement::SetDoubleAttribute( const char * name, double val )
{    
    char buf[256];
    #if defined(TIXML_SNPRINTF)        
        TIXML_SNPRINTF( buf, sizeof(buf), "%f", val );
    #else
        sprintf( buf, "%f", val );
    #endif
    SetAttribute( name, buf );
}


void TiXmlElement::SetAttribute( const char * cname, const char * cvalue )
{
    String _name( cname );
    String _value( cvalue );

    TiXmlAttribute* node = attributeSet.Find( _name );
    if ( node )
    {
        node->SetValue( _value );
        return;
    }

    TiXmlAttribute* attrib = new TiXmlAttribute( cname, cvalue );
    if ( attrib )
    {
        attributeSet.Add( attrib );
    }
    else
    {
        TiXmlDocument* document = GetDocument();
        if ( document ) document->SetError( TIXML_ERROR_OUT_OF_MEMORY, 0, 0, TIXML_ENCODING_UNKNOWN );
    }
}

void TiXmlElement::SetAttribute( const String& name, const String& _value )
{
    TiXmlAttribute* node = attributeSet.Find( name );
    if ( node )
    {
        node->SetValue( _value );
        return;
    }

    TiXmlAttribute* attrib = new TiXmlAttribute( name, _value );
    if ( attrib )
    {
        attributeSet.Add( attrib );
    }
    else
    {
        TiXmlDocument* document = GetDocument();
        if ( document ) document->SetError( TIXML_ERROR_OUT_OF_MEMORY, 0, 0, TIXML_ENCODING_UNKNOWN );
    }
}


void TiXmlElement::RemoveAttribute( const char * name )
{
    String str( name );
    TiXmlAttribute* node = attributeSet.Find( str );

    if ( node )
    {
        attributeSet.Remove( node );
        delete node;
    }
}


void TiXmlElement::Print( FILE* cfile, int depth ) const
{
    int i;
    assert( cfile );
    const char* indent = GetDocument() 
        ? GetDocument()->GetIndentChars()
        : DefaultIndentChars;
    for ( i=0; i<depth; i++ )
        fprintf( cfile, "%s", indent );

    fprintf( cfile, "<%s", value.c_str() );

    const TiXmlAttribute* attrib;
    for ( attrib = attributeSet.First(); attrib; attrib = attrib->Next() )
    {
        fprintf( cfile, " " );
        attrib->Print( cfile, depth );
    }

    // There are 3 different formatting approaches:
    // 1) An element without children is printed as a <foo /> node
    // 2) An element with only a text child is printed as <foo> text </foo>
    // 3) An element with children is printed on multiple lines.
    TiXmlNode* node;
    if ( !firstChild )
    {
        fprintf( cfile, " />" );
    }
    else if ( firstChild == lastChild && firstChild->ToText() )
    {
        fprintf( cfile, ">" );
        firstChild->Print( cfile, depth + 1 );
        fprintf( cfile, "</%s>", value.c_str() );
    }
    else
    {
        fprintf( cfile, ">" );

        for ( node = firstChild; node; node=node->NextSibling() )
        {
            if ( !node->ToText() )
            {
                fprintf( cfile, "\n" );
            }
            node->Print( cfile, depth+1 );
        }
        fprintf( cfile, "\n" );
        for( i=0; i<depth; ++i ) {
            fprintf( cfile, "%s", indent );
        }
        fprintf( cfile, "</%s>", value.c_str() );
    }
}


void TiXmlElement::CopyTo( TiXmlElement* target ) const
{
    // superclass:
    TiXmlNode::CopyTo( target );

    // Element class: 
    // Clone the attributes, then clone the children.
    const TiXmlAttribute* attribute = 0;
    for(    attribute = attributeSet.First();
    attribute;
    attribute = attribute->Next() )
    {
        target->SetAttribute( attribute->Name(), attribute->Value() );
    }

    TiXmlNode* node = 0;
    for ( node = firstChild; node; node = node->NextSibling() )
    {
        target->LinkEndChild( node->Clone() );
    }
}

bool TiXmlElement::Accept( TiXmlVisitor* visitor ) const
{
    if ( visitor->VisitEnter( *this, attributeSet.First() ) ) 
    {
        for ( const TiXmlNode* node=FirstChild(); node; node=node->NextSibling() )
        {
            if ( !node->Accept( visitor ) )
                break;
        }
    }
    return visitor->VisitExit( *this );
}


TiXmlNode* TiXmlElement::Clone() const
{
    TiXmlElement* clone = new TiXmlElement( Value() );
    if ( !clone )
        return 0;

    CopyTo( clone );
    return clone;
}


const char* TiXmlElement::GetText() const
{
    const TiXmlNode* child = this->FirstChild();
    if ( child ) {
        const TiXmlText* childText = child->ToText();
        if ( childText ) {
            return childText->Value();
        }
    }
    return 0;
}

