const TiXmlAttribute* TiXmlAttribute::Next() const
{
    // We are using knowledge of the sentinel. The sentinel
    // have a value or name.
    if ( next->value.empty() && next->name.empty() )
        return 0;
    return next;
}

/*
TiXmlAttribute* TiXmlAttribute::Next()
{
    // We are using knowledge of the sentinel. The sentinel
    // have a value or name.
    if ( next->value.empty() && next->name.empty() )
        return 0;
    return next;
}
*/

const TiXmlAttribute* TiXmlAttribute::Previous() const
{
    // We are using knowledge of the sentinel. The sentinel
    // have a value or name.
    if ( prev->value.empty() && prev->name.empty() )
        return 0;
    return prev;
}

/*
TiXmlAttribute* TiXmlAttribute::Previous()
{
    // We are using knowledge of the sentinel. The sentinel
    // have a value or name.
    if ( prev->value.empty() && prev->name.empty() )
        return 0;
    return prev;
}
*/

void TiXmlAttribute::Print( FILE* cfile, int /*depth*/, String* str ) const
{
    String n, v;

    EncodeString( name, &n );
    EncodeString( value, &v );

    if (value.find ('\"') == String::npos) {
        if ( cfile ) {
        fprintf (cfile, "%s=\"%s\"", n.c_str(), v.c_str() );
        }
        if ( str ) {
            (*str) += n; (*str) += "=\""; (*str) += v; (*str) += "\"";
        }
    }
    else {
        if ( cfile ) {
        fprintf (cfile, "%s='%s'", n.c_str(), v.c_str() );
        }
        if ( str ) {
            (*str) += n; (*str) += "='"; (*str) += v; (*str) += "'";
        }
    }
}


int TiXmlAttribute::QueryIntValue( int* ival ) const
{
    if ( TIXML_SSCANF( value.c_str(), "%d", ival ) == 1 )
        return TIXML_SUCCESS;
    return TIXML_WRONG_TYPE;
}

int TiXmlAttribute::QueryDoubleValue( double* dval ) const
{
    if ( TIXML_SSCANF( value.c_str(), "%lf", dval ) == 1 )
        return TIXML_SUCCESS;
    return TIXML_WRONG_TYPE;
}

void TiXmlAttribute::SetIntValue( int _value )
{
    char buf [64];
    #if defined(TIXML_SNPRINTF)        
        TIXML_SNPRINTF(buf, sizeof(buf), "%d", _value);
    #else
        sprintf (buf, "%d", _value);
    #endif
    SetValue (buf);
}

void TiXmlAttribute::SetDoubleValue( double _value )
{
    char buf [256];
    #if defined(TIXML_SNPRINTF)        
        TIXML_SNPRINTF( buf, sizeof(buf), "%lf", _value);
    #else
        sprintf (buf, "%lf", _value);
    #endif
    SetValue (buf);
}

int TiXmlAttribute::IntValue() const
{
    return atoi (value.c_str ());
}

double  TiXmlAttribute::DoubleValue() const
{
    return atof (value.c_str ());
}



//------------------------------------------------------------------------------
//                            TiXml COMMENT
//------------------------------------------------------------------------------

TiXmlComment::TiXmlComment( const TiXmlComment& copy ) : TiXmlNode( TiXmlNode::COMMENT )
{
    copy.CopyTo( this );
}


void TiXmlComment::operator=( const TiXmlComment& base )
{
    Clear();
    base.CopyTo( this );
}


void TiXmlComment::Print( FILE* cfile, int depth ) const
{
    assert( cfile );
    const char* indent = GetDocument() 
        ? GetDocument()->GetIndentChars()
        : DefaultIndentChars;
    for ( int i=0; i<depth; i++ )
        fprintf( cfile, "%s", indent );

    fprintf( cfile, "<!--%s-->", value.c_str() );
}


void TiXmlComment::CopyTo( TiXmlComment* target ) const
{
    TiXmlNode::CopyTo( target );
}


bool TiXmlComment::Accept( TiXmlVisitor* visitor ) const
{
    return visitor->Visit( *this );
}


TiXmlNode* TiXmlComment::Clone() const
{
    TiXmlComment* clone = new TiXmlComment();

    if ( !clone )
        return 0;

    CopyTo( clone );
    return clone;
}

//------------------------------------------------------------------------------
//                              TiXml TEXT
//------------------------------------------------------------------------------

void TiXmlText::Print( FILE* cfile, int depth ) const
{
    assert( cfile );
    if ( cdata )
    {
        int i;
        fprintf( cfile, "\n" );
        const char* indent = GetDocument() 
            ? GetDocument()->GetIndentChars()
            : DefaultIndentChars;
        for ( i=0; i<depth; i++ )
            fprintf( cfile, "%s", indent );

        fprintf( cfile, "<![CDATA[%s]]>\n", value.c_str() );    // unformatted output
    }
    else
    {
        String buffer;
        // sherm: Third argument says OK to keep quotes here 
        EncodeString( value, &buffer, true );
        fprintf( cfile, "%s", buffer.c_str() );
    }
}


void TiXmlText::CopyTo( TiXmlText* target ) const
{
    TiXmlNode::CopyTo( target );
    target->cdata = cdata;
}


bool TiXmlText::Accept( TiXmlVisitor* visitor ) const
{
    return visitor->Visit( *this );
}


TiXmlNode* TiXmlText::Clone() const
{    
    TiXmlText* clone = 0;
    clone = new TiXmlText( "" );

    if ( !clone )
        return 0;

    CopyTo( clone );
    return clone;
}



