    const Real xtol = Real(1e-12);
    const Real minlam = Real(1e-3);
    const int MaxIterations = 25;

    bool useNewtonIteration = true;

    // reset counter
    numGeodesicsShot = 0;

    // Define basis. This will not change during the solution.
