        Geodesic& geod) const override;

    const Function& getImplicitFunction() const override {
        return function;
    }

    static ContactGeometryTypeId classTypeId() {
        static const ContactGeometryTypeId id =
            createNewContactGeometryTypeId();
        return id;
    }
private:
