    for (i = nm1; i >= 1; --i) {
        c[i + j * c_dim1] = (c[i + j * c_dim1] - e[i * e_dim1 + 1] * c[i 
            + 1 + j * c_dim1]) / e[i * e_dim1];
    }
    }
    return 0;


L80:
    i__1 = *k;
    for (j = 1; j <= i__1; ++j) {
    c[j * c_dim1 + 1] = y[j * y_dim1 + 1];
    i__2 = *n;
    for (i = 2; i <= i__2; ++i) {
        i__3 = *m, i__4 = i - 1;
        mi = min(i__3,i__4);
        d = y[i + j * y_dim1];
        i__3 = mi;
        for (l = 1; l <= i__3; ++l) {
        d -= e[-l + i * e_dim1] * c[i - l + j * c_dim1];
        }
        c[i + j * c_dim1] = d;
    }
    c[*n + j * c_dim1] /= e[*n * e_dim1];
    for (i = nm1; i >= 1; --i) {
        i__2 = *m, i__3 = *n - i;
        mi = min(i__2,i__3);
        d = c[i + j * c_dim1];
        i__2 = mi;
        for (l = 1; l <= i__2; ++l) {
        d -= e[l + i * e_dim1] * c[i + l + j * c_dim1];
        }
        c[i + j * c_dim1] = d / e[i * e_dim1];
    }
    }
    return 0;
}



/* TRINV.FOR, 1985-06-03 */


SimTK_Real trinv_(SimTK_Real *b, SimTK_Real *e, int *m, int *n)
{
    /* System generated locals */
    int b_dim1, b_offset, e_dim1, e_offset, i__1, i__2, i__3;
    SimTK_Real ret_val;

    /* Local variables */
    int i, j, k;
    SimTK_Real dd, dl;
    int mi;
    SimTK_Real du;
    int mn, mp;



/* ***  Assess central 2*M+1 bands of E**-1 and store in array E */

    /* Parameter adjustments */

    e_dim1 = *m - (-(*m)) + 1;
    e_offset = -(*m) + e_dim1;
    e -= e_offset;

    b_dim1 = *m - (-(*m)) + 1;
    b_offset = -(*m) + b_dim1;
    b -= b_offset;

    /* Function Body */
    e[*n * e_dim1] = 1 / e[*n * e_dim1];
    for (i = *n - 1; i >= 1; --i) {
    i__1 = *m, i__2 = *n - i;
    mi = min(i__1,i__2);
    dd = 1 / e[i * e_dim1];
    i__1 = mi;
    for (k = 1; k <= i__1; ++k) {
        e[k + *n * e_dim1] = e[k + i * e_dim1] * dd;
        e[-k + e_dim1] = e[-k + (k + i) * e_dim1];
    }
    dd += dd;
    for (j = mi; j >= 1; --j) {
        du = 0.;
        dl = 0.;
        i__1 = mi;
        for (k = 1; k <= i__1; ++k) {
        du -= e[k + *n * e_dim1] * e[j - k + (i + k) * e_dim1];
        dl -= e[-k + e_dim1] * e[k - j + (i + j) * e_dim1];
        }
        e[j + i * e_dim1] = du;
        e[-j + (j + i) * e_dim1] = dl;
        dd -= e[j + *n * e_dim1] * dl + e[-j + e_dim1] * du;
    }
    e[i * e_dim1] = dd / 2;
    }

    dd = 0.;
    i__1 = *n;
    for (i = 1; i <= i__1; ++i) {
    i__2 = *m, i__3 = i - 1;
    mn = -min(i__2,i__3);
    i__2 = *m, i__3 = *n - i;
    mp = min(i__2,i__3);
    i__2 = mp;
    for (k = mn; k <= i__2; ++k) {
        dd += b[k + i * b_dim1] * e[-k + (k + i) * e_dim1];
    }
    }
    ret_val = dd;
    i__1 = *m;
    for (k = 1; k <= i__1; ++k) {
    e[k + *n * e_dim1] = 0.;
    e[-k + e_dim1] = 0.;
    }
    return ret_val;
} 



