/* SEARCH.FOR, 1985-06-03 */


int search_(int *n, const SimTK_Real *x, SimTK_Real *t, 
    int *l)
{
    int il, iu;

    /* Parameter adjustments */

    --x;

    /* Function Body */

    if (*t < x[1]) {
    *l = 0;
    return 0;
    }
    if (*t >= x[*n]) {
    *l = *n;
    return 0;
    }
    *l = max(*l,1);
    if (*l >= *n) {
    *l = *n - 1;
    }

    if (*t >= x[*l]) {
    goto L5;
    }
    --(*l);
    if (*t >= x[*l]) {
    return 0;
    }

    il = 1;
L3:
    iu = *l;
L4:
    *l = (il + iu) / 2;
    if (iu - il <= 1) {
    return 0;
    }
    if (*t < x[*l]) {
    goto L3;
    }
    il = *l;
    goto L4;
L5:
    if (*t < x[*l + 1]) {
    return 0;
    }
    ++(*l);
    if (*t < x[*l + 1]) {
    return 0;
    }
    il = *l + 1;
    iu = *n;
    goto L4;

}

