#include "simmath/Integrator.h"
#include "simmath/internal/common.h"

#include "SimTKcommon.h"

namespace SimTK {
class Integrator;

/**
 * This class uses an Integrator to advance a System through time.  For example:
 *
 * <pre>
 * TimeStepper stepper(system, integrator);
 * stepper.initialize(initialState);
 * stepper.stepTo(finalTime);
 * </pre>
 *
 * stepTo() invokes the Integrator to advance time.  It detects events which may occur, calls event handlers
 * as appropriate, then invokes the Integrator again to continue advancing time until the target time is
 * reached.
 */
class SimTK_SIMMATH_EXPORT TimeStepper {
    public:
    /**
     * Create a TimeStepper to advance a System.
     *
     * This constructor leaves the Integrator unspecified.  You therefore must call setIntegrator()
     * before calling initialize().
     */
    explicit TimeStepper(const System& system);
    /**
     * Create a TimeStepper to advance a System using an Integrator.
     */
    TimeStepper(const System& system, Integrator& integrator);
    ~TimeStepper();
    /**
     * Set the Integrator this TimeStepper will use to advance the System.
     */
    void setIntegrator(Integrator& integrator);
    /**
     * Get the Integrator being used to advance the System.
     */
    const Integrator& getIntegrator() const;
    /**
     * Get a non-const reference to the Integrator being used to advance the System.
     */
    Integrator& updIntegrator();
    /**
     * Get whether the TimeStepper should report every significant state returned by the Integrator.
     * If this is true, stepTo() will return whenever the Integrator reports a significant state,
     * such as when an event occurs or the start of a new continuous interval.  If this is false,
     * stepTo() will only return when the specified time has been reached or when the simulation is
     * terminated.
     */
    bool getReportAllSignificantStates() const;
    /**
     * Set whether the TimeStepper should report every significant state returned by the Integrator.
     * If this is true, stepTo() will return whenever the Integrator reports a significant state,
     * such as when an event occurs or the start of a new continuous interval.  If this is false,
     * stepTo() will only return when the specified time has been reached or when the simulation is
     * terminated.
     */
    void setReportAllSignificantStates(bool b);
    /**
     * Supply the time stepper with a starting state.  This must be called after the Integrator has
     * been set, and before the first call to stepTo().
     *
     * The specified state is copied into the Integrator's internally maintained "advanced" state;
     * subsequent changes to the State object passed in here will not affect the simulation.
     */
    void initialize(const State&);
    /**
     * Get the current State of the System being integrated.  Usually this will correspond to the
     * time specified in the most recent call to stepTo().  It may be an interpolated state which
     * is earlier than the Integrator's "advanced" state.
     */
    const State& getState() const;
    /**
     * Get the current time of the System being integrated.  This is identical to calling
     * getState().getTime().
     */
    Real getTime() const {
        return getState().getTime();
    }
    /**
     * Use the Integrator to advance the System up to the specified time.  This method will repeatedly
     * invoke the Integrator as necessary, handling any events which occur.  The TimeStepper must be
     * initialized by calling initialize() before this method may be called.
     *
     * When this method returns, the System will usually have been advanced all the way to the specified
     * final time.  There are situations where it may return sooner, however: if
     * setReportAllSignificantStates() was set to true, and a significant state occurred; if {@link
     * Integrator#setFinalTime setFinalTime()} was invoked on the Integrator, and the final time was reached;
     * or if an event handler requested that the simulation terminate immediately.
     */
    Integrator::SuccessfulStepStatus stepTo(Real time);

    /*! <!-- Stage info --> */
    const void PrintStages() const {
        PrintAdvancedStateStages();
        PrintInterpolatedStateStages();
    };

    const void PrintAdvancedStateStages() const;
    const void PrintInterpolatedStateStages() const;

    private:
    class TimeStepperRep* rep;
    friend class TimeStepperRep;
};

} // namespace SimTK

#endif // SimTK_SIMMATH_TIMESTEPPER_H_

#ifndef SimTK_SIMMATH_VERLET_INTEGRATOR_H_ #define SimTK_SIMMATH_VERLET_INTEGRATOR_H_
/* -------------------------------------------------------------------------- * * Simbody(tm): SimTKmath * * -------------------------------------------------------------------------- * * This is part of the SimTK biosimulation toolkit originating from * * Simbios, the NIH National Center for Physics-Based Simulation of * * Biological Structures at Stanford, funded under the NIH Roadmap for * * Medical Research, grant U54 GM072970. See https://simtk.org/home/simbody. * * * * Portions copyright (c) 2007-12 Stanford University and the Authors. * * Authors: Peter Eastman * * Contributors: * * * * Licensed under the Apache License, Version 2.0 (the "License"); you may * * not use this file except in compliance with the License. You may obtain a * * copy of the License at http://www.apache.org/licenses/LICENSE-2.0. * * * * Unless required by applicable law or agreed to in writing, software * * distributed under the License is distributed on an "AS IS" BASIS, * * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. * * See the License for the specific language governing permissions and * * limitations under the License. * * -------------------------------------------------------------------------- */
#include "SimTKcommon.h" #include "simmath/internal/common.h" #include "simmath/Integrator.h"
namespace SimTK {
class VerletIntegratorRep;
/** * This is an Integrator based on the velocity Verlet algorithm. It is a third order, semi-explicit integrator. * Velocity independent forces only need to be evaluated once per time step, but forces which depend on velocity * must be evaluated multiple times. This makes it a very efficient algorithm for systems where most of the time * is spent evaluating forces that depend only on position. * * Although this is a third order integrator, the velocities reported at each time step are only accurate to lower * order. If any forces depend on velocity, this may lead to a reduction in the overall accuracy of integration, * since the forces being integrated are less accurate than the method used to integrate them. Whether this * actually happens in a particular case depends on the magnitude of the velocity dependent forces, how sensitive * they are to errors in velocity, and how the system is affected by those forces. * * When this integrator is used with fixed size time steps, it is symplectic. This means that it is extremely * good at conserving energy, and will usually produce much less variation in energy than most other integrators * would at the same step size. This makes it a good choice for problems where accurate energy conservation over * long time periods is important. To use it in this way, use the constructor which takes a step size, or call * setFixedStepSize(). * * Alternatively, it may be used in variable step mode, in which case the step size is selected based on the * accuracy specified by calling setAccuracy(). In this case it is no longer symplectic, so the energy will * fluctuate more over time. Because the step size is adjusted based on the local error in each step, however, * the trajectory will generally be more accurate in variable step size mode than would be obtained with the * same number of fixed size steps spanning the same amount of time. * * Another possible strategy is to set only a maximum step size but not a minimum step size. It should be chosen * such that most time steps will use the fixed maximum step size, but smaller steps can be used when necessary to * preserve accuracy. This leads to fairly good long term energy conservation, while still maintaining reasonable * accuracy when unusually large forces transiently occur. */
class SimTK_SIMMATH_EXPORT VerletIntegrator : public Integrator { public: /** * Create a VerletIntegrator for integrating a System with variable size steps. */ explicit VerletIntegrator(const System& sys); /** * Create a VerletIntegrator for integrating a System with fixed size steps. */ VerletIntegrator(const System& sys, Real stepSize); };
} // namespace SimTK
#endif // SimTK_SIMMATH_VERLET_INTEGRATOR_H_

