template <>
void EigenRep<float>::copyVectors(Matrix_<std::complex<float>>& vectors) { // non-symmetric
    int i, j;

    vectors.resize(n, valuesFound);
    for (j = 0; j < valuesFound; j++) {
        for (i = 0; i < n; i++) {
            vectors(i, j) = complexEigenVectors.data[j * n + i];
        }
    }
}
