#include <complex>
#include <cassert>
#include <iostream>


namespace SimTK {

template <typename T>
class TypedWorkSpace {
    public:

    // copy constructor
    TypedWorkSpace( const TypedWorkSpace& c ) {
        size = c.size;

        if( size == 0 ) {
             data = 0;
         } else {
             data = new T[size];
             for(int i=0;i<size;i++) data[i] = c.data[i];
         }

    }
    TypedWorkSpace& operator=(const TypedWorkSpace& rhs) {
        if (&rhs == this)
            return *this;

        delete [] data;
        data = 0;
        size = rhs.size;

        if( size > 0) {
             data = new T[size];
             for(int i=0;i<size;i++) data[i] = rhs.data[i];
        }
        return *this;
    }

    explicit TypedWorkSpace( int n ) {
        size = n;
        data = (n==0 ? 0 : new T[n]);
    }

    TypedWorkSpace() : size(0), data(0) { }

    ~TypedWorkSpace() {
        delete [] data;
    }

    void resize( int n ) {
        delete [] data;
        size = n;
        data = (n==0 ? 0 : new T[n]);
    }

    int size;
    T* data; 
};

} // namespace SimTK
#endif // SimTK_SIMMATH_WORK_SPACE_H_

