    DBG_START_METH("CompoundVector::SumImpl", dbg_verbosity);
    DBG_ASSERT(vectors_valid_);
    Number sum=0.;
    for(Index i=0; i<NComps(); i++) {
      sum += ConstComp(i)->Sum();
