using SimTK::Real;

/* Table of constant values */

const static Real c_b9 = 0.;
const static int c__1 = 1;
/* static int c__9 = 9; */
const static int c__11 = 11;
/* static int c__3 = 3; */
const static Real c_b275 = Real(.001);
const static Real c_b276 = Real(.9);
const static Real c_b277 = Real(.1);
/* static int c__5 = 5; */
// Reordering function calls could prevent the need for defining these statics before use.
static int dtrsl_(Real* t, int* ldt, int* n, Real* b, const int* job, int* info);
static int hpsolb_(int* n, Real* t, int* iorder, int* iheap);
static int dcsrch_(Real* f,
                   Real* g,
                   Real* stp,
                   const Real* ftol,
                   const Real* gtol,
                   const Real* xtol,
                   const Real* stpmin,
                   Real* stpmax,
                   char* task,
                   int* isave,
                   Real* dsave,
                   ftnlen task_len);
static int dcstep_(Real* stx,
                   Real* fx,
                   Real* dx,
                   Real* sty,
                   Real* fy,
                   Real* dy,
                   Real* stp,
                   Real* fp,
                   Real* dp,
                   bool* brackt,
                   Real* stpmin,
                   Real* stpmax);

static Real timer() {
    return ((Real)(std::clock()) / CLOCKS_PER_SEC);
}

/* Subroutine */
static int active_(int* n,
                   Real* l,
                   Real* u,
                   int* nbd,
                   Real* x,
                   int* iwhere,
                   int* iprint,
                   bool* prjctd,
                   bool* cnstnd,
                   bool* boxed) {
    /* Format strings */
    /*
        static char fmt_1001[] = "(/,\002At X0 \002,i9,\002 variables are exactl\
    y at the bounds\002)";
    */

    /* System generated locals */
    int i__1;

    /* Local variables */
    int nbdd, i__;

    /* Fortran I/O blocks */
    /*
        static cilist io___81 = { 0, 6, 0, 0, 0 };
        static cilist io___82 = { 0, 6, 0, 0, 0 };
        static cilist io___83 = { 0, 6, 0, fmt_1001, 0
    */


    /*     ************ */

    /*     Subroutine active */

    /*     This subroutine initializes iwhere and projects the initial x to */
    /*       the feasible set if necessary. */

    /*     iwhere is an int array of dimension n. */
    /*       On entry iwhere is unspecified. */
    /*       On exit iwhere(i)=-1  if x(i) has no bounds */
    /*                         3   if l(i)=u(i) */
    /*                         0   otherwise. */
    /*       In cauchy, iwhere is given finer gradations. */


    /*                           *  *  * */

    /*     NEOS, November 1994. (Latest revision June 1996.) */
    /*     Optimization Technology Center. */
    /*     Argonne National Laboratory and Northwestern University. */
    /*     Written by */
    /*                        Ciyou Zhu */
    /*     in collaboration with R.H. Byrd, P. Lu-Chen and J. Nocedal. */


    /*     ************ */
    /*     Initialize nbdd, prjctd, cnstnd and boxed. */
    /* Parameter adjustments */
    --iwhere;
    --x;
    --nbd;
    --u;
    --l;

    /* Function Body */
    nbdd = 0;
    *prjctd = FALSE_;
    *cnstnd = FALSE_;
    *boxed = TRUE_;
    /*     Project the initial x to the easible set if necessary. */
    i__1 = *n;
    for (i__ = 1; i__ <= i__1; ++i__) {
        if (nbd[i__] > 0) {
            if (nbd[i__] <= 2 && x[i__] <= l[i__]) {
                if (x[i__] < l[i__]) {
                    *prjctd = TRUE_;
                    x[i__] = l[i__];
                }
                ++nbdd;
            } else if (nbd[i__] >= 2 && x[i__] >= u[i__]) {
                if (x[i__] > u[i__]) {
                    *prjctd = TRUE_;
                    x[i__] = u[i__];
                }
                ++nbdd;
            }
        }
        /* L10: */
    }
    /*     Initialize iwhere and assign values to cnstnd and boxed. */
    i__1 = *n;
    for (i__ = 1; i__ <= i__1; ++i__) {
        if (nbd[i__] != 2) {
