    /*                 =-D^(-1/2)p1+D^(-1)L'p2. */
    i__1 = *col;
    for (i__ = 1; i__ <= i__1; ++i__) {
        p[i__] = -p[i__] / std::sqrt(sy[i__ + i__ * sy_dim1]);
        /* L40: */
