/* Subroutine */
static int cmprlb_(int* n,
                   int* m,
                   Real* x,
                   Real* g,
                   Real* ws,
                   Real* wy,
                   Real* sy,
                   Real* wt,
                   Real* z__,
                   Real* r__,
                   Real* wa,
                   int* index,
                   Real* theta,
                   int* col,
                   int* head,
                   int* nfree,
                   bool* cnstnd,
                   int* info) {
