    /*     Subspace minimization. */

    /* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
    /*     Form  the LEL^T factorization of the indefinite */
    /*       matrix    K = [-D -Y'ZZ'Y/theta     L_a'-R_z'  ] */
    /*                     [L_a -R_z           theta*S'AA'S ] */
    /*       where     E = [-I  0] */
    /*                     [ 0  I] */
    if (wrk) {
        formk_(n,
               &nfree,
               &index[1],
               &nenter,
               &ileave,
               &indx2[1],
               &iupdat,
               &updatd,
               &wn[wn_offset],
               &snd[snd_offset],
               m,
               &ws[ws_offset],
               &wy[wy_offset],
               &sy[sy_offset],
               &theta,
               &col,
               &head,
               &info);
    }
    if (info != 0) {
        /*          nonpositive definiteness in Cholesky factorization; */
        /*          refresh the lbfgs memory and restart the iteration. */
        if (*iprint >= 1) {
            /*
                    s_wsfe(&io___68);
                    e_wsfe();
            */
        }
        info = 0;
        col = 0;
        head = 1;
        theta = 1.;
        iupdat = 0;
        updatd = FALSE_;
        cpu2 = timer();
        sbtime = sbtime + cpu2 - cpu1;
        goto L222;
    }
    /*        compute r=-Z'B(xcp-xk)-Z'g (using wa(2m+1)=W'(xcp-x) */
    /*                                                   from 'cauchy'). */
    cmprlb_(n,
            m,
            &x[1],
            &g[1],
            &ws[ws_offset],
            &wy[wy_offset],
            &sy[sy_offset],
            &wt[wt_offset],
            &z__[1],
            &r__[1],
            &wa[1],
            &index[1],
            &theta,
            &col,
            &head,
            &nfree,
            &cnstnd,
            &info);
    if (info != 0) {
        goto L444;
    }
    /*       call the direct method. */
    subsm_(n,
           m,
           &nfree,
           &index[1],
           &l[1],
           &u[1],
           &nbd[1],
           &z__[1],
           &r__[1],
           &ws[ws_offset],
           &wy[wy_offset],
           &theta,
           &col,
           &head,
           &iword,
           &wa[1],
           &wn[wn_offset],
           iprint,
           &info);
L444:
    if (info != 0) {
        /*          singular triangular system detected; */
        /*          refresh the lbfgs memory and restart the iteration. */
        if (*iprint >= 1) {
            /*
                    s_wsfe(&io___69);
                    e_wsfe();
            */
        }
        info = 0;
        col = 0;
        head = 1;
        theta = 1.;
        iupdat = 0;
        updatd = FALSE_;
        cpu2 = timer();
        sbtime = sbtime + cpu2 - cpu1;
        goto L222;
    }
    cpu2 = timer();
    sbtime = sbtime + cpu2 - cpu1;
L555:
    /* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */

    /*     Line search and optimality tests. */

    /* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
    /*     Generate the search direction d:=z-x. */
    i__1 = *n;
    for (i__ = 1; i__ <= i__1; ++i__) {
        d__[i__] = z__[i__] - x[i__];
        /* L40: */
    }
L666:
    lnsrlb_(n,
            &l[1],
            &u[1],
            &nbd[1],
            &x[1],
            f,
            &fold,
            &gd,
            &gdold,
            &g[1],
            &d__[1],
            &r__[1],
            &t[1],
            &z__[1],
            &stp,
            &dnorm,
            &dtd,
            &xstep,
            &stpmx,
            &iter,
            &ifun,
            &iback,
            &nfgv,
            &info,
            task,
            &boxed,
            &cnstnd,
            csave,
            &isave[22],
            &dsave[17],
            (ftnlen)60,
            (ftnlen)60);
    if (info != 0 || iback >= 20) {
        /*          restore the previous iterate. */
        DCOPY(*n, &t[1], (const int&)c__1, &x[1], (const int&)c__1);
        DCOPY(*n, &r__[1], (const int&)c__1, &g[1], (const int&)c__1);
        *f = fold;
        if (col == 0) {
            /*             abnormal termination. */
            if (info == 0) {
                info = -9;
                /*                restore the actual number of f and g evaluations etc. */
                --nfgv;
                --ifun;
                --iback;
            }
            strcpy(task, "ABNORMAL_TERMINATION_IN_LNSRCH");
            ++iter;
            goto L999;
        } else {
            /*             refresh the lbfgs memory and restart the iteration. */
            if (*iprint >= 1) {
                /*
                        s_wsfe(&io___71);
                        e_wsfe();
                */
            }
            if (info == 0) {
                --nfgv;
            }
            info = 0;
            col = 0;
            head = 1;
            theta = 1.;
            iupdat = 0;
            updatd = FALSE_;
            strcpy(task, "RESTART_FROM_LNSRCH");
            cpu2 = timer();
            lnscht = lnscht + cpu2 - cpu1;
            goto L222;
        }
    } else if (strncmp(task, "FG_LN", 5) == 0) {
        /*          return to the driver for calculating f and g; reenter at 666. */
        goto L1000;
    } else {
        /*          calculate and print out the quantities related to the new X. */
        cpu2 = timer();
        lnscht = lnscht + cpu2 - cpu1;
        ++iter;
        /*        Compute the infinity norm of the projected (-)gradient. */
        projgr_(n, &l[1], &u[1], &nbd[1], &x[1], *f, &g[1], &sbgnrm);
        /*        Print iteration information. */
        prn2lb_(n,
                &x[1],
                f,
                &g[1],
                iprint,
                &itfile,
                &iter,
                &nfgv,
                &nact,
                &sbgnrm,
                &nint,
                word,
                &iword,
                &iback,
                &stp,
                &xstep,
                (ftnlen)3);
        goto L1000;
    }
L777:
    /*     Test for termination. */
    if (sbgnrm <= *pgtol) {
        /*                                terminate the algorithm. */
        strcpy(task, "CONVERGENCE: NORM OF PROJECTED GRADIENT <= PGTOL");
        goto L999;
    }
    /* Computing MAX */
    d__1 = fabs(fold), d__2 = fabs(*f), d__1 = std::max(d__1, d__2);
    ddum = std::max(d__1, Real(1));
    if (fold - *f <= tol * ddum) {
        /*                                        terminate the algorithm. */
        strcpy(task, "CONVERGENCE: REL_REDUCTION_OF_F <= FACTR*EPSMCH");
        if (iback >= 10) {
            info = -5;
        }
        /*           i.e., to issue a warning if iback>10 in the line search. */
        goto L999;
    }
    /*     Compute d=newx-oldx, r=newg-oldg, rr=y'y and dr=y's. */
    i__1 = *n;
    for (i__ = 1; i__ <= i__1; ++i__) {
        r__[i__] = g[i__] - r__[i__];
        /* L42: */
    }
    rr = DDOT(*n, &r__[1], (const int&)c__1, &r__[1], (const int&)c__1);
    if (stp == 1.) {
        dr = gd - gdold;
        ddum = -gdold;
    } else {
        dr = (gd - gdold) * stp;
        DSCAL(*n, (const Real&)stp, &d__[1], (const int&)c__1);
        ddum = -gdold * stp;
    }
    if (dr <= epsmch * ddum) {
        /*                            skip the L-BFGS update. */
        ++nskip;
        updatd = FALSE_;
        if (*iprint >= 1) {
            /*
                    s_wsfe(&io___75);
                    do_fio(&c__1, (char *)&dr, (ftnlen)sizeof(Real));
                    do_fio(&c__1, (char *)&ddum, (ftnlen)sizeof(Real));
                    e_wsfe();
            */
        }
        goto L888;
    }
    /* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */

    /*     Update the L-BFGS matrix. */

    /* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
    updatd = TRUE_;
    ++iupdat;
    /*     Update matrices WS and WY and form the middle matrix in B. */
    matupd_(n,
            m,
            &ws[ws_offset],
            &wy[wy_offset],
            &sy[sy_offset],
            &ss[ss_offset],
            &d__[1],
            &r__[1],
            &itail,
            &iupdat,
            &col,
            &head,
            &theta,
            &rr,
            &dr,
            &stp,
            &dtd);
    /*     Form the upper half of the pds T = theta*SS + L*D^(-1)*L'; */
    /*        Store T in the upper triangular of the array wt; */
    /*        Cholesky factorize T to J*J' with */
    /*           J' stored in the upper triangular of wt. */
    formt_(m, &wt[wt_offset], &sy[sy_offset], &ss[ss_offset], &col, &theta, &info);
    if (info != 0) {
        /*          nonpositive definiteness in Cholesky factorization; */
        /*          refresh the lbfgs memory and restart the iteration. */
        if (*iprint >= 1) {
            /*
                    s_wsfe(&io___76);
                    e_wsfe();
            */
        }
        info = 0;
        col = 0;
        head = 1;
        theta = 1.;
        iupdat = 0;
        updatd = FALSE_;
        goto L222;
    }
/*     Now the inverse of the middle matrix in B is */
/*       [  D^(1/2)      O ] [ -D^(1/2)  D^(-1/2)*L' ] */
/*       [ -L*D^(-1/2)   J ] [  0        J'          ] */
L888:
    /* -------------------- the end of the loop ----------------------------- */
    goto L222;
L999:
    time2 = timer();
    time = time2 - time1;
    prn3lb_(n,
            &x[1],
            f,
            task,
            iprint,
            &info,
            &itfile,
            &iter,
            &nfgv,
            &nintol,
            &nskip,
            &nact,
            &sbgnrm,
            &time,
            &nint,
            word,
            &iback,
            &stp,
            &xstep,
            &k,
            &cachyt,
            &sbtime,
            &lnscht,
            (ftnlen)60,
            (ftnlen)3);
L1000:
    /*     Save local variables. */
    lsave[1] = prjctd;
    lsave[2] = cnstnd;
    lsave[3] = boxed;
    lsave[4] = updatd;
    isave[1] = nintol;
    isave[3] = itfile;
    isave[4] = iback;
    isave[5] = nskip;
    isave[6] = head;
    isave[7] = col;
    isave[8] = itail;
    isave[9] = iter;
    isave[10] = iupdat;
    isave[12] = nint;
    isave[13] = nfgv;
    isave[14] = info;
    isave[15] = ifun;
    isave[16] = iword;
    isave[17] = nfree;
    isave[18] = nact;
    isave[19] = ileave;
    isave[20] = nenter;
    dsave[1] = theta;
    dsave[2] = fold;
    dsave[3] = tol;
    dsave[4] = dnorm;
    dsave[5] = epsmch;
    dsave[6] = cpu1;
    dsave[7] = cachyt;
    dsave[8] = sbtime;
    dsave[9] = lnscht;
    dsave[10] = time1;
    dsave[11] = gd;
    dsave[12] = stpmx;
    dsave[13] = sbgnrm;
    dsave[14] = stp;
    dsave[15] = gdold;
    dsave[16] = dtd;
    return 0;
} /* mainlb_ */

/* ======================= The end of mainlb ============================= */

/* ================    L-BFGS-B (version 2.1)   ========================== */
/* Subroutine */
int SimTK::LBFGSBOptimizer::setulb_(int* n,
                                    int* m,
                                    Real* x,
                                    Real* l,
                                    Real* u,
                                    int* nbd,
                                    Real* f,
                                    Real* g,
                                    Real* factr,
                                    Real* pgtol,
                                    Real* wa,
                                    int* iwa,
                                    char* task,
                                    int* iprint,
                                    char* csave,
                                    bool* lsave,
                                    int* isave,
                                    Real* dsave,
                                    long task_len,
                                    long csave_len) {
    /* System generated locals */
    int i__1;

    /* Local variables */
    int lsnd, lsgo, lygo, /* l1,  l2, l3, */ ld, lr, lt;
    int lz, lwa, lsg, lyg, lwn, lss, lws, lwt, lsy, lwy, lyy;
    (void)task_len;
    (void)csave_len;

    /*     ************ */

    /*     Subroutine setulb */

    /*     This subroutine partitions the working arrays wa and iwa, and */
    /*       then uses the limited memory BFGS method to solve the bound */
    /*       constrained optimization problem by calling mainlb. */
    /*       (The direct method will be used in the subspace minimization.) */

    /*     n is an int variable. */
    /*       On entry n is the dimension of the problem. */
    /*       On exit n is unchanged. */

    /*     m is an int variable. */
    /*       On entry m is the maximum number of variable metric corrections */
    /*         used to define the limited memory matrix. */
    /*       On exit m is unchanged. */

    /*     x is a double precision array of dimension n. */
    /*       On entry x is an approximation to the solution. */
    /*       On exit x is the current approximation. */

    /*     l is a double precision array of dimension n. */
    /*       On entry l is the lower bound on x. */
    /*       On exit l is unchanged. */

    /*     u is a double precision array of dimension n. */
    /*       On entry u is the upper bound on x. */
    /*       On exit u is unchanged. */

    /*     nbd is an int array of dimension n. */
    /*       On entry nbd represents the type of bounds imposed on the */
    /*         variables, and must be specified as follows: */
    /*         nbd(i)=0 if x(i) is unbounded, */
    /*                1 if x(i) has only a lower bound, */
    /*                2 if x(i) has both lower and upper bounds, and */
    /*                3 if x(i) has only an upper bound. */
    /*       On exit nbd is unchanged. */

    /*     f is a double precision variable. */
    /*       On first entry f is unspecified. */
    /*       On final exit f is the value of the function at x. */

    /*     g is a double precision array of dimension n. */
    /*       On first entry g is unspecified. */
    /*       On final exit g is the value of the gradient at x. */

    /*     factr is a double precision variable. */
    /*       On entry factr >= 0 is specified by the user.  The iteration */
    /*         will stop when */

    /*         (f^k - f^{k+1})/max{|f^k|,|f^{k+1}|,1} <= factr*epsmch */

    /*         where epsmch is the machine precision, which is automatically */
    /*         generated by the code. Typical values for factr: 1.d+12 for */
    /*         low accuracy; 1.d+7 for moderate accuracy; 1.d+1 for extremely */
    /*         high accuracy. */
    /*       On exit factr is unchanged. */

    /*     pgtol is a double precision variable. */
    /*       On entry pgtol >= 0 is specified by the user.  The iteration */
    /*         will stop when */

    /*                 max{|proj g_i | i = 1, ..., n} <= pgtol */

    /*         where pg_i is the ith component of the projected gradient. */
    /*       On exit pgtol is unchanged. */

    /*     wa is a double precision working array of length */
    /*       (2mmax + 4)nmax + 12mmax^2 + 12mmax. */

    /*     iwa is an int working array of length 3nmax. */

    /*     task is a working string of characters of length 60 indicating */
    /*       the current job when entering and quitting this subroutine. */

    /*     iprint is an int variable that must be set by the user. */
    /*       It controls the frequency and type of output generated: */
    /*        iprint<0    no output is generated; */
    /*        iprint=0    print only one line at the last iteration; */
    /*        0<iprint<99 print also f and |proj g| every iprint iterations; */
    /*        iprint=99   print details of every iteration except n-vectors; */
    /*        iprint=100  print also the changes of active set and final x; */
    /*        iprint>100  print details of every iteration including x and g; */
    /*       When iprint > 0, the file iterate.dat will be created to */
    /*                        summarize the iteration. */

    /*     csave is a working string of characters of length 60. */

    /*     lsave is a bool working array of dimension 4. */
    /*       On exit with 'task' = NEW_X, the following information is */
    /*                                                             available: */
    /*         If lsave(1) = .true.  then  the initial X has been replaced by */
    /*                                     its projection in the feasible set; */
    /*         If lsave(2) = .true.  then  the problem is constrained; */
    /*         If lsave(3) = .true.  then  each variable has upper and lower */
    /*                                     bounds; */

    /*     isave is an int working array of dimension 44. */
    /*       On exit with 'task' = NEW_X, the following information is */
    /*                                                             available: */
    /*         isave(22) = the total number of intervals explored in the */
    /*                         search of Cauchy points; */
    /*         isave(26) = the total number of skipped BFGS updates before */
    /*                         the current iteration; */
    /*         isave(30) = the number of current iteration; */
    /*         isave(31) = the total number of BFGS updates prior the current */
    /*                         iteration; */
    /*         isave(33) = the number of intervals explored in the search of */
    /*                         Cauchy point in the current iteration; */
    /*         isave(34) = the total number of function and gradient */
    /*                         evaluations; */
    /*         isave(36) = the number of function value or gradient */
    /*                                  evaluations in the current iteration; */
    /*         if isave(37) = 0  then the subspace argmin is within the box; */
    /*         if isave(37) = 1  then the subspace argmin is beyond the box; */
    /*         isave(38) = the number of free variables in the current */
    /*                         iteration; */
    /*         isave(39) = the number of active constraints in the current */
    /*                         iteration; */
    /*         n + 1 - isave(40) = the number of variables leaving the set of */
    /*                           active constraints in the current iteration; */
    /*         isave(41) = the number of variables entering the set of active */
    /*                         constraints in the current iteration. */

    /*     dsave is a double precision working array of dimension 29. */
    /*       On exit with 'task' = NEW_X, the following information is */
    /*                                                             available: */
    /*         dsave(1) = current 'theta' in the BFGS matrix; */
    /*         dsave(2) = f(x) in the previous iteration; */
    /*         dsave(3) = factr*epsmch; */
    /*         dsave(4) = 2-norm of the line search direction vector; */
    /*         dsave(5) = the machine precision epsmch generated by the code; */
    /*         dsave(7) = the accumulated time spent on searching for */
    /*                                                         Cauchy points; */
    /*         dsave(8) = the accumulated time spent on */
    /*                                                 subspace minimization; */
    /*         dsave(9) = the accumulated time spent on line search; */
    /*         dsave(11) = the slope of the line search function at */
    /*                                  the current point of line search; */
    /*         dsave(12) = the maximum relative step length imposed in */
    /*                                                           line search; */
    /*         dsave(13) = the infinity norm of the projected gradient; */
    /*         dsave(14) = the relative step length in the line search; */
    /*         dsave(15) = the slope of the line search function at */
    /*                                 the starting point of the line search; */
    /*         dsave(16) = the square of the 2-norm of the line search */
    /*                                                      direction vector. */

    /*     Subprograms called: */

    /*       L-BFGS-B Library ... mainlb. */


    /*     References: */

    /*       [1] R. H. Byrd, P. Lu, J. Nocedal and C. Zhu, ``A limited */
    /*       memory algorithm for bound constrained optimization'', */
    /*       SIAM J. Scientific Computing 16 (1995), no. 5, pp. 1190--1208. */

    /*       [2] C. Zhu, R.H. Byrd, P. Lu, J. Nocedal, ``L-BFGS-B: a */
    /*       limited memory FORTRAN code for solving bound constrained */
    /*       optimization problems'', Tech. Report, NAM-11, EECS Department, */
    /*       Northwestern University, 1994. */

    /*       (Postscript files of these papers are available via anonymous */
    /*        ftp to eecs.nwu.edu in the directory pub/lbfgs/lbfgs_bcm.) */

    /*                           *  *  * */

    /*     NEOS, November 1994. (Latest revision June 1996.) */
    /*     Optimization Technology Center. */
    /*     Argonne National Laboratory and Northwestern University. */
    /*     Written by */
    /*                        Ciyou Zhu */
    /*     in collaboration with R.H. Byrd, P. Lu-Chen and J. Nocedal. */


    /*     ************ */
    /* Parameter adjustments */
    --iwa;
    --g;
    --nbd;
    --u;
    --l;
    --x;
    --wa;
    --lsave;
    --isave;
    --dsave;

    /* Function Body */
    if (strncmp(task, "START", 5) == 0) {
        isave[1] = *m * *n;
        /* Computing 2nd power */
        i__1 = *m;
        isave[2] = i__1 * i__1;
        /* Computing 2nd power */
        i__1 = *m;
        isave[3] = i__1 * i__1 << 2;
        isave[4] = 1;
        isave[5] = isave[4] + isave[1];
        isave[6] = isave[5] + isave[1];
        isave[7] = isave[6] + isave[2];
        isave[8] = isave[7] + isave[2];
        isave[9] = isave[8] + isave[2];
        isave[10] = isave[9] + isave[2];
        isave[11] = isave[10] + isave[3];
        isave[12] = isave[11] + isave[3];
        isave[13] = isave[12] + *n;
        isave[14] = isave[13] + *n;
        isave[15] = isave[14] + *n;
        isave[16] = isave[15] + *n;
        isave[17] = isave[16] + (*m << 3);
        isave[18] = isave[17] + *m;
        isave[19] = isave[18] + *m;
        isave[20] = isave[19] + *m;
    }
    /* l1 = isave[1];
    l2 = isave[2];
    l3 = isave[3]; */
    lws = isave[4];
    lwy = isave[5];
    lsy = isave[6];
    lss = isave[7];
    lyy = isave[8];
    lwt = isave[9];
    lwn = isave[10];
    lsnd = isave[11];
    lz = isave[12];
    lr = isave[13];
    ld = isave[14];
    lt = isave[15];
    lwa = isave[16];
    lsg = isave[17];
    lsgo = isave[18];
    lyg = isave[19];
    lygo = isave[20];
    mainlb_(n,
            m,
            &x[1],
            &l[1],
            &u[1],
            &nbd[1],
            f,
            &g[1],
            factr,
            pgtol,
            &wa[lws],
            &wa[lwy],
            &wa[lsy],
            &wa[lss],
            &wa[lyy],
            &wa[lwt],
            &wa[lwn],
            &wa[lsnd],
            &wa[lz],
            &wa[lr],
            &wa[ld],
            &wa[lt],
            &wa[lwa],
            &wa[lsg],
            &wa[lsgo],
            &wa[lyg],
            &wa[lygo],
            &iwa[1],
            &iwa[*n + 1],
            &iwa[(*n << 1) + 1],
            task,
            iprint,
            csave,
            &lsave[1],
            &isave[22],
            &dsave[1],
            (ftnlen)60,
            (ftnlen)60);
    return 0;
} /* setulb_ */

