        // 	// updSubZMatrixBATsToAllWorlds(replicaIx);

        // 	if(wPart.nofNonequilibriumWorlds){
        // 		setReplicasWorldsParameters(replicaIx, false, true, mixIndex);
        // 		transferCoordsFromReplicaToWorld(replicaIx, thermoWorldIxs[wPart.N1_wCnt]);
