/*!
 * <!--  -->
 */
double HMCSampler::studyBATScale(const SimTK::State& someState) {
    // Accumulate result here
    SimTK::Real logBATJacobian = 0.0;

    system.get().realize(someState, SimTK::Stage::Position);

    world.get().updateAtomListsFromSimbody(someState);

    // Molecules
    for (std::size_t topoIx = 0; topoIx < topologies.size(); topoIx++) {
        Topology& topology = topologies[topoIx];

        // Atoms
        for (SimTK::Compound::AtomIndex aIx(0); aIx < topology.getNumAtoms(); ++aIx) {
            // Is this atom a root atom for a body
            if (topology.getAtomLocationInMobilizedBodyFrameThroughDumm(aIx, dumm) == 0) {
                SimTK::Real bondLength = SimTK::NaN;
                SimTK::Real bondAngle = SimTK::NaN;

                // Get body and parentBody
                SimTK::MobilizedBodyIndex mbx = topology.getAtomMobilizedBodyIndexThroughDumm(aIx, dumm);
                const SimTK::MobilizedBody& mobod = matter.get().getMobilizedBody(mbx);
                const SimTK::Transform& X_PF = mobod.getDefaultInboardFrame();
                const SimTK::Transform& X_BM = mobod.getDefaultOutboardFrame();
                const SimTK::Transform& X_FM = mobod.getMobilizerTransform(someState);

                const SimTK::MobilizedBody& parentMobod = mobod.getParentMobilizedBody();
                SimTK::MobilizedBodyIndex parentMbx = parentMobod.getMobilizedBodyIndex();

                // world.get().determineMobilityFrom_H(mbx, someState);

                // Rotations signs
                SimTK::Transform X_GF = parentMobod.getBodyTransform(someState) * X_PF;
                SimTK::UnitVec3 G_FZdir = X_GF.R() * SimTK::UnitVec3(0, 0, 1);
                SimTK::UnitVec3 G_FYdir = X_GF.R() * SimTK::UnitVec3(0, 1, 0);
                int ZSign = 1;
                int YSign = 1;

                if (X_BM.p().norm() < 0.00000001) { // Cartesian

                    std::cout << "studyBATScale " << " Cartesian" << "\n";
                    continue;

                } else { // non-Cartesian

                    // (### 1 ###) Accumulate initial BAT values
                    if (parentMbx == 0) {
                        continue;
                    } // Ground

                    // Get the neighbor atom in the parent mobilized body
                    const auto chemParentAIx = topology.getChemicalParentOfMobodRootAtom(aIx, matter, dumm);

                    if (chemParentAIx < 0) {
                        continue;
                    } // no parent ??

                    // Get Top frame
                    SimTK::Transform G_X_root =
                        topology.getTopLevelTransform() * topology.getTopTransform(aIx);

                    // Get Top to parent frame
                    const auto& topoAtomPair = world.get().getMobodRootAtomIndex(parentMbx);
                    const auto parentRootAIx = topoAtomPair.cAIx;

                    SimTK::Transform G_X_Proot =
                        topology.getTopLevelTransform() * topology.getTopTransform(parentRootAIx);

                    // chemical parent atom
                    SimTK::Transform G_X_chemProot =
                        topology.getTopLevelTransform() * topology.getTopTransform(chemParentAIx);

                    const auto V3 = (~(G_X_root.R())) * G_X_root.p();
                    const auto V2 = (~(G_X_root.R())) * G_X_chemProot.p();
                    const auto G_ParentRoot = V3 - V2;

                    // BEGIN GET ANGLE
                    SimTK::Compound::AtomIndex chemGrandParentIx;
                    SimTK::Transform G_X_grand;

                    if (chemParentAIx >= 1) {
                        chemGrandParentIx = topology.getInboardAtomIndex(chemParentAIx);

                        G_X_grand =
                            topology.getTopLevelTransform() * topology.getTopTransform(chemGrandParentIx);

                        const auto V1 = (~(G_X_root.R())) * G_X_grand.p();

                        const auto G_GrandParent = V2 - V1;

                        const auto crossDiffVec = G_ParentRoot % G_GrandParent;
                        const auto crossDiff = SimTK::UnitVec3(crossDiffVec.normalize()[0],
                                                               crossDiffVec.normalize()[1],
                                                               crossDiffVec.normalize()[2]);

                        ZSign = (crossDiff[0] * G_FZdir[0]) + (crossDiff[1] * G_FZdir[1])
                                + (crossDiff[2] * G_FZdir[2]);
                        YSign = (crossDiff[0] * G_FYdir[0]) + (crossDiff[1] * G_FYdir[1])
                                + (crossDiff[2] * G_FYdir[2]);

                        bondLength = std::sqrt((G_ParentRoot[0] * G_ParentRoot[0])
                                               + (G_ParentRoot[1] * G_ParentRoot[1])
                                               + (G_ParentRoot[2] * G_ParentRoot[2]));
                        bondAngle = calculateAngleInRad(V2, V1, V3);

                        // scout("studyBATScale ") << "mbx " << mbx << " " << "bondDist " << bondLength <<" "
                        // << "bondAngle " << bondAngle
                        // <<" crossDiff " << crossDiff[0] <<" " << crossDiff[1] <<" " << crossDiff[2]
                        // <<" G_FZdir " << G_FZdir[0] <<" "  << G_FZdir[1] <<" " << G_FZdir[2]
                        // <<" ZSign "<< (crossDiff[0] * G_FZdir[0]) + (crossDiff[1] * G_FZdir[1]) +
                        // (crossDiff[2] * G_FZdir[2])
                        // <<" YSign "<< (crossDiff[0] * G_FYdir[0]) + (crossDiff[1] * G_FYdir[1]) +
                        // (crossDiff[2] * G_FYdir[2])
                        // << eol;

                    } // atom has a grandParent

                    // (### 2 ###) Add any modifications from qs
                    SimTK::Vec3 checkV = X_BM.R() * SimTK::Vec3(1, 0, 0);

                    if (std::abs((checkV[0] - 0.0)) < 0.00000001) { // Pin, Cylinder, Spherical, BallF

                        std::cout << "studyBATScale " << " Pin, Cylinder, Spherical, BallF" << "\n";

                        if (mobod.getNumQ(someState) >= 3) { // Spherical or Ball

                            // bondAngle += YSign * mobod.getOneQ(someState, 1); // direction ?
                        }

                    } else { // Slider, AnglePin, BendStretch

                        std::cout << "studyBATScale " << " Slider, AnglePin, BendStretch" << "\n";

                        if (mobod.getNumQ(someState) == 2) { // BendStretch

                            // bondAngle += ZSign * mobod.getOneQ(someState, 0); // direction ?
                        }
                    }

                    // (### 3 ###) Cook Jacobian
                    if (!(std::isnan(bondLength))) {
                        logBATJacobian += 4.0 * std::log(bondLength);
                    }
                    if (!(std::isnan(bondAngle))) {
                        logBATJacobian += 2.0 * std::log(std::sin(bondAngle));
                    }

                } // non-Cartesian case

            } // if atom is root

        } // every atom

    } // every topology

    return logBATJacobian;
}

/*! <!-- Doesn't take masses into account -->
 */
auto HMCSampler::calcMobodsMBAT(const SimTK::State& someState) -> SimTK::Real {
    system.get().realize(someState, SimTK::Stage::Position);
    world.get().updateAtomListsFromSimbody(someState);

    // Accumulate result here
    SimTK::Real logBATJacobian = 0.0;

    // We calculate mobilized body BAT Jacobian determinant
    // This means that we only need the atom bonds between rigid bodies (already computed when initializing
    // the world)
    for (const auto& bond : world.get().getRigidBodyAtomBonds()) {
        // Skip Cartesian bonds
        if (bond.mobility == SimTK::BondMobility::Mobility::Translation) {
            continue;
        }

        // Get a reference to the current topology
        const auto& topology = topologies[bond.topologyIndex];

        // Get atom locations in ground frame
        const SimTK::Vec3 V3 =
            topology.calcAtomLocationInGroundFrameThroughSimbody(bond.childCAIx, dumm, matter, someState);
        const SimTK::Vec3 V2 =
            topology.calcAtomLocationInGroundFrameThroughSimbody(bond.parentCAIx, dumm, matter, someState);

        // Add bond length contribution to Jacobian
        const SimTK::Real bondLength = (V3 - V2).norm();
        logBATJacobian += 4.0 * std::log(bondLength);

        // Check if we can calculate bond angle contribution (we need three atoms)
        // If parent is 0, then no grandparent exists (it's bonded to ground)
        if (bond.parentCAIx > 0) {
            const SimTK::Vec3 V1 = topology.calcAtomLocationInGroundFrameThroughSimbody(bond.grandParentCAIx,
                                                                                        dumm,
                                                                                        matter,
                                                                                        someState);
            const SimTK::Real bondAngle = calculateAngleInRad(V2, V1, V3);
            logBATJacobian += 2.0 * std::log(std::sin(bondAngle));
        }
    }

    return logBATJacobian;
}

// this is how we compute fixman: adding contributions of bond lengths and angles between rigid bodies (as you
// can see, we skip bonds and angles inside rigid bodies) what do you think of this code? is this
// scientifically correct? is it clear enough? how would you test it? it is guaranteed that: bonds and angles
// are unconstrained, there is exactly one parent per body we are integrating directly in internal
// coordinates. i checked the implementation of verlet integrator and it uses q and u directly

/*! <!-- Doesn't take masses into account -->
 */
auto HMCSampler::calcMobodsBATJacobianDetLog_NEW(const SimTK::State& someState) -> SimTK::Real {
    // Accumulate result here
    SimTK::Real logBATJacobian = 0.0;

    system.get().realize(someState, SimTK::Stage::Position);

    world.get().updateAtomListsFromSimbody(someState);

    // Molecules
    for (auto& topology : topologies) {
        // Atoms
        for (SimTK::Compound::AtomIndex aIx(0); aIx < topology.getNumAtoms(); ++aIx) {
            // Is this atom a root atom for a body
            if (topology.getAtomLocationInMobilizedBodyFrameThroughDumm(aIx, dumm) != 0) {
                continue;
            }

            SimTK::Real bondLength = SimTK::NaN;
            SimTK::Real bondAngle = SimTK::NaN;

            // Get body and parentBody
            SimTK::MobilizedBodyIndex mbx = topology.getAtomMobilizedBodyIndexThroughDumm(aIx, dumm);
            const SimTK::MobilizedBody& mobod = matter.get().getMobilizedBody(mbx);

            const SimTK::MobilizedBody& parentMobod = mobod.getParentMobilizedBody();
            SimTK::MobilizedBodyIndex parentMbx = parentMobod.getMobilizedBodyIndex();

            // (### 1 ###) Accumulate initial BAT values
            if (parentMbx == 0) {
                continue;
            } // Ground

            // Get the neighbor atom in the parent mobilized body
            SimTK::Compound::AtomIndex chemParentAIx =
                topology.getChemicalParentOfMobodRootAtom(aIx, matter, dumm); // Victor bug fix

            if (chemParentAIx.isValid() && chemParentAIx.isValidExtended()) {
                if (chemParentAIx < 0) {
                    continue;
                }
            } else {
                continue;
            }

            // Get Top to parent frame
            const auto& topoAtomPair = world.get().getMobodRootAtomIndex(parentMbx);
            const auto parentRootAIx = topoAtomPair.cAIx;

            const auto V3 =
                topology.calcAtomLocationInGroundFrameThroughSimbody(aIx, dumm, matter, someState);
            const auto V2 =
                topology.calcAtomLocationInGroundFrameThroughSimbody(chemParentAIx, dumm, matter, someState);
            const auto G_ParentRoot = V3 - V2;

            bondLength = std::sqrt((G_ParentRoot[0] * G_ParentRoot[0]) + (G_ParentRoot[1] * G_ParentRoot[1])
                                   + (G_ParentRoot[2] * G_ParentRoot[2]));
            // scout("calcMobodsMBAT ") << "mbx " << mbx << " " << "bondDist " << bondLength;

            // GET ANGLE
            if (chemParentAIx >= 1) {
                SimTK::Compound::AtomIndex chemGrandParentIx;
                chemGrandParentIx = topology.getInboardAtomIndex(chemParentAIx);
                const auto V1 = topology.calcAtomLocationInGroundFrameThroughSimbody(chemGrandParentIx,
                                                                                     dumm,
                                                                                     matter,
                                                                                     someState);
                const auto G_GrandParent = V2 - V1;
                bondAngle = calculateAngleInRad(V2, V1, V3);
                // scout(" ") << "bondAngle " << bondAngle;
            } // atom has a grandParent

            // scout(" ") << eol;

            // (### 3 ###) Cook Jacobian
            if (!(std::isnan(bondLength))) {
                logBATJacobian += 2.0 * std::log(bondLength);
            }
            if (!(std::isnan(bondAngle))) {
                logBATJacobian += std::log(std::sin(bondAngle));
            }

        } // every atom

    } // every topology

    return logBATJacobian;
}

#include "NUTS.hpp"

void NUTSNodeRef::copyVectorsFrom(const NUTSNodeRef& src) const {
    nuts_detail::copyVec(minus_q, src.minus_q, n);
    nuts_detail::copyVec(minus_p, src.minus_p, n);
    nuts_detail::copyVec(plus_q, src.plus_q, n);
    nuts_detail::copyVec(plus_p, src.plus_p, n);
    nuts_detail::copyVec(proposal_q, src.proposal_q, n);
    nuts_detail::copyVec(proposal_p, src.proposal_p, n);
}

void NUTSNodeRef::copyProposalFrom(const NUTSNodeRef& src) {
    nuts_detail::copyVec(proposal_q, src.proposal_q, n);
    nuts_detail::copyVec(proposal_p, src.proposal_p, n);
    proposedEnergy = src.proposedEnergy;
    proposalLeafIndex = src.proposalLeafIndex;
}

void NUTSWorkspaceSimbody::init(int maxDepth, int nDOF) {
    this->nDOF = nDOF;

    // Layout (in units of nDOF doubles)
    //   pool nodes : maxDepth * 2 * 6
    //   treeRoot   : 6
    //   pTemp      : 1
    //   total      : (maxDepth * 12 + 8) * nDOF
    //
    // Alignment: 64 bytes (one cache line).  With AVX-256 each cache line
    // holds 8 doubles; aligning to 64 bytes means all dot-product inner
    // loops start on a vector-unit boundary -> compiler can emit aligned
    // vmovapd / vfmadd231pd without scalar prologue.
    constexpr std::size_t kAlign = 64;
    slabDoubles = static_cast<std::size_t>((maxDepth * 12) + 8) * nDOF;
    const std::size_t rawBytes = slabDoubles * sizeof(SimTK::Real);
    const std::size_t alignedBytes = ((rawBytes + kAlign - 1) / kAlign) * kAlign;

    deallocate();
    slab = allocAligned(alignedBytes, kAlign);
    std::memset(slab, 0, alignedBytes);

    // Carve up the slab
    SimTK::Real* ptr = slab;

    auto nextVec = [&]() -> SimTK::Real* {
        SimTK::Real* p = ptr;
        ptr += nDOF;
        return p;
    };

    nodePool.resize(maxDepth);
    for (auto& pair : nodePool) {
        for (NUTSNodeRef* ref : {pair.data(), &pair[1]}) {
            ref->minus_q = nextVec();
            ref->minus_p = nextVec();
            ref->plus_q = nextVec();
            ref->plus_p = nextVec();
            ref->proposal_q = nextVec();
            ref->proposal_p = nextVec();
            ref->n = nDOF;
        }
    }

    treeRoot.minus_q = nextVec();
    treeRoot.minus_p = nextVec();
    treeRoot.plus_q = nextVec();
    treeRoot.plus_p = nextVec();
    treeRoot.proposal_q = nextVec();
    treeRoot.proposal_p = nextVec();
    treeRoot.n = nDOF;

    pTemp = nextVec();

    // assert(ptr == slab + slabDoubles); // sanity: used exactly what we planned

    // SimTK adapter - one heap allocation, reused every leaf
    pTempSimTK.resize(nDOF);
}

// U-turn check
auto NUTSWorkspaceSimbody::isUTurn(const NUTSNodeRef& node) -> bool {
    SimTK::Real dot1;
    SimTK::Real dot2;
    nuts_detail::wrapDot(node.minus_q, node.plus_q, node.minus_p, node.plus_p, node.n, dot1, dot2);
    return (dot1 < 0.0) || (dot2 < 0.0);
}

auto NUTSWorkspaceSimbody::allocAligned(std::size_t bytes, std::size_t align) -> SimTK::Real* {
    auto* ptr = static_cast<SimTK::Real*>(std::aligned_alloc(align, bytes));
    if (ptr == nullptr) {
        throw std::bad_alloc{};
    }
    return ptr;
}

void NUTSWorkspaceSimbody::deallocate() {
    if (slab != nullptr) {
        std::free(slab);
        slab = nullptr;
    }
}

void NUTSTrajectoryLog::printOneLiner() const {
    static const char* stopAbbr[] = {"NotNUTS", "MaxDepth", "UTurn", "SubUTurn", "NoValid"};

    const int valid = static_cast<int>(std::count_if(events.begin(), events.end(), [](const LeafEvent& e) {
        return e.sliceValid;
    }));
    const int total = totalSteps();

    // Time extents (in whatever units timestep is expressed)
    const SimTK::Real tMin = -static_cast<SimTK::Real>(bwdSteps) * timestep;
    const SimTK::Real tMax = static_cast<SimTK::Real>(fwdSteps) * timestep;
    const SimTK::Real tSel = static_cast<SimTK::Real>(selectedStepIndex) * timestep;

    std::ostringstream oss;
    oss << std::fixed << std::setprecision(4);
    oss << "\t - [NUTS] d=" << finalDepth << " | " << stopAbbr[static_cast<int>(stopReason)] << " | " << total
        << " steps" << " (bwd:" << -bwdSteps << " fwd:+" << fwdSteps << ")" << " | t=[" << tMin << " ps, +"
        << tMax << " ps]" << " | sel=" << (tSel >= 0 ? "+" : "") << tSel << " ps | valid=" << valid << "/"
        << total;

    std::cout << oss.str() << "\n";
}

void NUTSTrajectoryLog::printTable() const {
    static const char* stopStr[] = {"NotUsingNUTS",
                                    "MaxDepth",
                                    "U-turn",
                                    "Subtree U-turn",
                                    "NoValidProposals"};

    std::cout << std::fixed << std::setprecision(4);
    std::cout << "\n  ┌─ NUTS trajectory ───────────────────────────────────────────────┐\n";
    std::cout << "  │  H0 = " << std::setw(12) << H0 << "   log u = " << std::setw(12) << logU
              << "   slice Δ = " << std::setw(8) << sliceWindow << "  │\n";
    std::cout << "  │  Depth = " << finalDepth << "   Steps = " << totalSteps()
              << "   Stop: " << stopStr[static_cast<int>(stopReason)]
              << "   Selected: " << (selectedStepIndex >= 0 ? "+" : "") << selectedStepIndex << "\n";
    std::cout << "  ├────────┬──────┬──────────────┬───────┬──────────┤\n";
    std::cout << "  │  Step  │ Dir  │      H       │ Valid │ Selected │\n";
    std::cout << "  ├────────┼──────┼──────────────┼───────┼──────────┤\n";

    std::cout << "  │  +0000 │ init │ " << std::setw(12) << H0 << " │  yes  │ "
              << (selectedStepIndex == 0 ? "   ←   " : "       ") << "│\n";

    auto sorted = events;
    std::sort(sorted.begin(), sorted.end(), [](const LeafEvent& a, const LeafEvent& b) {
        return a.stepIndex < b.stepIndex;
    });

    for (const auto& e : sorted) {
        const char* dirStr = (e.direction == NUTSDirection::Forward) ? "fwd " : "bwd ";
        char stepBuf[8];
        std::snprintf(stepBuf, sizeof(stepBuf), "%+05d", e.stepIndex);
        std::cout << "  │  " << stepBuf << " │ " << dirStr << " │ " << std::setw(12) << e.H << " │  "
                  << (e.sliceValid ? "yes" : "no ") << "  │ "
                  << (e.stepIndex == selectedStepIndex ? "   ←   " : "       ") << "│\n";
    }
    std::cout << "  └────────┴──────┴──────────────┴───────┴──────────┘\n\n";
}

