#include "Random.hpp"

Random32 buildRandom32(uint32_t seed) {
    std::seed_seq seedSeq{seed, seed + 1, seed + 2};
    std::array<uint32_t, 3> seeds;
    seedSeq.generate(seeds.begin(), seeds.end());

    const uint64_t seed_bits = (uint64_t(seeds[0]) << 32) | seeds[1];

    return Random32{seed_bits};
}

Random64 buildRandom64(Random32& seeder) {
    const auto high = (uint64_t(seeder()) << 32) | (seeder() & 0xFFFFFFFF);
    const auto low = (uint64_t(seeder()) << 32) | (seeder() & 0xFFFFFFFF);

    return Random64{PCG_128BIT_CONSTANT(high, low)};
}

void RANDOM_CACHE::initialize(int argNU) {
    nu = argNU;
    V.resize(nu);

    FillWithGaussian();
}

int RANDOM_CACHE::getNU() const {
    return nu;
}

void RANDOM_CACHE::setSeed(Random32& seeder) {
    Random64 = buildRandom64(seeder);
}

void RANDOM_CACHE::generateGaussianVelocities() {
    task = std::async(std::launch::async, FillWithGaussian);
}

void RANDOM_CACHE::wait() {
    task.wait();
}

const SimTK::Vector& RANDOM_CACHE::getV() const {
    return V;
}

#include "Replica.hpp"

#include "Compound.h"

// Get coordinates from this replica
const std::vector<SimTK::Compound::AtomTargetLocations>& Replica::getAtomsLocationsInGround() const {
    return atomsLocations;
}

// Get coordinates from this replica
const std::vector<SimTK::Compound::AtomTargetLocations>& Replica::get_WORK_AtomsLocationsInGround() const {
    return WORK_atomsLocations;
}

// Set the coordinates of this replica
void Replica::setAtomsLocationsInGround(
    const std::vector<SimTK::Compound::AtomTargetLocations>& atomTargets) {
    atomsLocations = atomTargets;

    // Allocate memory for coordinate buffers
    if (x.size() == 0) {
        for (const auto& topology : atomsLocations) {
            for (const auto& locations : topology) {
                x.push_back(0.0);
                y.push_back(0.0);
                z.push_back(0.0);
            }
        }
    }

    // Update coordinate buffers
    int numAtomsInMols = 0;
    for (const auto& topology : atomsLocations) {
        for (SimTK::Compound::AtomIndex atomIndex(0); atomIndex < topology.size(); ++atomIndex) {
            x[atomIndex + numAtomsInMols] = topology[atomIndex][0];
            y[atomIndex + numAtomsInMols] = topology[atomIndex][1];
            z[atomIndex + numAtomsInMols] = topology[atomIndex][2];
        }
        numAtomsInMols += topology.size();
    }
}

// Set the coordinates of this replica
// Also allocate memory
void Replica::set_WORK_AtomsLocationsInGround(
    const std::vector<SimTK::Compound::AtomTargetLocations>& atomTargets) {
    WORK_atomsLocations = atomTargets;
}

void Replica::updAtomsLocationsInGround_FromWORK() {
    atomsLocations = WORK_atomsLocations;

    // Allocate memory for coordinate buffers
    if (x.size() == 0) {
        for (const auto& topology : atomsLocations) {
            for (const auto& locations : topology) {
                x.push_back(0.0);
                y.push_back(0.0);
                z.push_back(0.0);
            }
        }
    }

    // Update coordinate buffers
    int numAtomsInMols = 0;
    for (const auto& topology : atomsLocations) {
        for (SimTK::Compound::AtomIndex atomIndex(0); atomIndex < topology.size(); ++atomIndex) {
            x[atomIndex + numAtomsInMols] = topology[atomIndex][0];
            y[atomIndex + numAtomsInMols] = topology[atomIndex][1];
            z[atomIndex + numAtomsInMols] = topology[atomIndex][2];
        }
        numAtomsInMols += topology.size();
    }
}

// Update the coordinates of this replica
void Replica::upd_WORK_AtomsLocationsInGround(
    const std::vector<SimTK::Compound::AtomTargetLocations>& atomTargets) {
    WORK_atomsLocations = atomTargets;
}

