std::vector<SimTK::Real>& ThermodynamicState::getBATVarsRow(int rowIndex) {
    assert(rowIndex >= 0 && rowIndex < zMatrixBATVars.size() && "Invalid row index");

    return zMatrixBATVars[rowIndex];
}

/*!
 * <!--  -->
 */
void ThermodynamicState::allocQStatsFirstDimension() {
    // Resize
    BMps_diffs.resize(worldIndexes.size());
    BMps_means.resize(worldIndexes.size());

    PFrs_diffs.resize(worldIndexes.size());
    PFrs_means.resize(worldIndexes.size());

    currQs.resize(worldIndexes.size());
    Qmeans.resize(worldIndexes.size());
    Qdiffs.resize(worldIndexes.size());
    Qvars.resize(worldIndexes.size());
}

/*!
 * <!--
 * N starts at 1 -->
 */
double instantAverage(int N, double prevAvg, double currSam) {
    SimTK_ASSERT(N > 0, "N must be gt 0");

    SimTK::Real N_1_over_N = (N - 1.0) / N;
    // Avoid numerical instability
    // if(N > 10000){
    // 	N_1_over_N = 1.0;
    // }else{
    // 	N_1_over_N = (N - 1.0) / N;
    // }

    SimTK::Real Ninv = 1.0 / N;

    return (N_1_over_N * prevAvg) + (Ninv * currSam);
}

/*!
 * <!-- not found = -1 -->
 */
int ThermodynamicState::findWorld(const int whichWorld) {
    int wPosInVector = -1;
    for (const auto wIx : worldIndexes) {
        wPosInVector++;
        if (whichWorld == wIx) {
            // wPosInVector = wIx;
            // break;
            return wPosInVector;
        }
    }
    return wPosInVector;
}

