        //     // worldQs.size() << " N " << N <<" Qvars: "; for(int qIx = 0; qIx < worldQs.size();
        //     // qIx++){std::cout <<" " << Qvars[wPosInVector][qIx];}std::cout << "\n";
        // } // )))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))) // @@@@@@@@@@@@@

    } else { // nofSamples gt 2

        for (int mbx = 0; mbx < worldBMps.size(); mbx++) {
            BMps_diffs[wPosInVector][mbx] = worldBMps[mbx] - BMps_means[wPosInVector][mbx];

            BMps_means[wPosInVector][mbx] =
                (N_1_over_N * BMps_means[wPosInVector][mbx]) + (Ninv * worldBMps[mbx]); // running mean
        }

        for (int mbx = 0; mbx < worldPFrs.size(); mbx++) {
            PFrs_diffs[wPosInVector][mbx] = worldPFrs[mbx] - PFrs_means[wPosInVector][mbx];

            PFrs_means[wPosInVector][mbx] =
                (N_1_over_N * PFrs_means[wPosInVector][mbx]) + (Ninv * worldPFrs[mbx]); // running mean
        }

        // Update Q means
        for (int qIx = 0; qIx < worldQs.size(); qIx++) {
            currQs[wPosInVector][qIx] = worldQs[qIx];
        }

        // Update Q means
        for (int qIx = 0; qIx < worldQs.size(); qIx++) {
            Qmeans[wPosInVector][qIx] = instantAverage(N, Qmeans[wPosInVector][qIx], worldQs[qIx]);
        }

        // Update Q differences
        for (int qIx = 0; qIx < worldQs.size(); qIx++) {
            Qdiffs[wPosInVector][qIx] = worldQs[qIx] - Qmeans[wPosInVector][qIx];
        }

        // Update Q variances
        for (int qIx = 0; qIx < worldQs.size(); qIx++) {
            Qvars[wPosInVector][qIx] = (N_1_over_N * Qvars[wPosInVector][qIx])
                                       + (Ninv * (Qdiffs[wPosInVector][qIx] * Qdiffs[wPosInVector][qIx]));
        }

        if (false
            //&& ((whichWorld == 0) || (whichWorld == 3) || (whichWorld == 4))
        ) { // (((((((((((((((((((((((((((((((((((((((((((((((((((((((((( // @@@@@@@@@@@@@
            int decimal_places = 7;
            std::cout << std::setw(6 + decimal_places) << std::fixed << std::setprecision(decimal_places);
            std::cout << "\n";

            // std::cout << "calcQStats thIx " << myIndex << " wIx " << whichWorld  << " nq " <<
            // worldPFrs.size() << " N " << N <<" PFrs: "; for(int mbx = 0; mbx < worldPFrs.size();
            // mbx++){std::cout <<" " << worldPFrs[mbx];}std::cout << "\n"; std::cout << "calcQStats thIx
            // " << myIndex << " wIx " << whichWorld  << " nq " << worldBMps.size() << " N " << N <<" BMps: ";
            // for(int mbx = 0; mbx < worldBMps.size(); mbx++){std::cout <<" " << worldBMps[mbx];}std::cout <<
            // std::endl;

            // std::cout << "calcQStats thIx " << myIndex << " wIx " << whichWorld  << " nq " <<
            // worldPFrs.size() << " N " << N <<" PFrs_means: "; for(int mbx = 0; mbx < worldPFrs.size();
            // mbx++){std::cout <<" " << PFrs_means[wPosInVector][mbx];}std::cout << "\n";

            std::cout << "calcQStats thIx " << myIndex << " wIx " << whichWorld << " nq " << worldBMps.size()
                      << " N " << N << " BMps_means: ";
            for (int mbx = 0; mbx < worldBMps.size(); mbx++) {
                std::cout << " " << BMps_means[wPosInVector][mbx];
            }
            std::cout << "\n";
            std::cout << "calcQStats thIx " << myIndex << " wIx " << whichWorld << " nq " << worldBMps.size()
                      << " N " << N << " BMps_diffs: ";
            for (int mbx = 0; mbx < worldBMps.size(); mbx++) {
                std::cout << " " << BMps_diffs[wPosInVector][mbx];
            }
            std::cout << "\n";

            // std::cout << "calcQStats thIx " << myIndex << " wIx " << whichWorld  << " nq " <<
            // worldQs.size() << " N " << N <<" currQs: "; for(int qIx = 0; qIx < worldQs.size();
            // qIx++){std::cout <<" " << currQs[wPosInVector][qIx];}std::cout << "\n"; std::cout <<
            // "calcQStats thIx " << myIndex << " wIx " << whichWorld << " nq " << worldQs.size() << " N " <<
            // N <<" qs: "; for(int qIx = 0; qIx < worldQs.size(); qIx++){std::cout <<" " <<
            // worldQs[qIx];}std::cout << "\n"; std::cout << "calcQStats thIx " << myIndex << " wIx " <<
            // whichWorld  << " nq " << worldQs.size() << " N " << N <<" Qmeans: "; for(int qIx = 0; qIx <
            // worldQs.size(); qIx++){std::cout <<" " << Qmeans[wPosInVector][qIx];}std::cout << "\n";
            // std::cout << "calcQStats thIx " << myIndex << " wIx " << whichWorld  << " nq " <<
            // worldQs.size() << " N " << N <<" Qdiffs: "; for(int qIx = 0; qIx < worldQs.size();
            // qIx++){std::cout <<" " << Qdiffs[wPosInVector][qIx];}std::cout << "\n";
            // std::cout << "\ncalcQStats thIx " << myIndex << " wIx " << whichWorld  << " nq " <<
            // worldQs.size() << " N " << N <<" Qvars: "; for(int qIx = 0; qIx < worldQs.size();
            // qIx++){std::cout <<" " << Qvars[wPosInVector][qIx];}std::cout << "\n";
        } // )))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))) // @@@@@@@@@@@@@

    } // nofSamples gt 2

    return true;
}

/*!
 * <!--  -->
 */
void ThermodynamicState::printQStats() {
    int wPosInVector = -1;
    for (const auto wIx : worldIndexes) {
        wPosInVector++;

        std::cout << "thIx " << myIndex << " wIx " << wIx << " nq " << Qmeans[wPosInVector].size() << " N "
                  << nofSamples + 1 << " : ";
        for (int qIx = 0; qIx < Qmeans[wPosInVector].size(); qIx++) {
            std::cout << " " << Qmeans[wPosInVector][qIx];
        }
        std::cout << "\n";
    }
}

